// ═══════════════════════════════════════════════════════
// _mlab – gemeinsames Mess-Framework fuer die Mechanik-Sims (Jg. 11)
// Generische Ausgleichsrechnung + Plot + Funktionsplotter, analog zu
// den _fpm*-Funktionen des Federpendels, aber parametrisiert ueber ein
// uebergebenes State-Objekt st und seine Presets. Wiederverwendet die
// bereits vorhandenen Helfer _fpmNum, _fpmFitOrigin, _fpmFitLinear,
// _fpmMakeFn, _fpmTicks, _fpmTickLbl (global aus dem Federpendel-Modul).
//
// Preset-Objekt P:
//   xl, yl                Achsenbeschriftung (Strings)
//   x(r), y(r)            Zeile -> Diagrammkoordinate
//   grp(r) | null         Gruppierung (z. B. je Objekt); null = eine Reihe
//   gl(key)               Legendentext einer Gruppe
//   slope(key) | undef    erwartete Steigung (fuer "erwartet:")
//   curve  | undef        true = nichtlineare Auftragung (kein Fit)
//   curveFn(xv,key)|undef  Theoriekurve (fuer curve bzw. showTheory)
//   note                  Hinweistext unter dem Fit
//   typ, form, param(), term(), deutung   Box "Erwarteter Funktionstyp"
//   ergebnis(fit) | undef  HTML-Block: gesuchte Groesse + Literaturvergleich
// ═══════════════════════════════════════════════════════

const _MLAB_PALETTE = ['#7c3aed', '#f97316', '#0284c7', '#16a34a', '#db2777', '#0891b2'];

// ── Ausgleichsrechnung + Plot ──────────────────────────
function _mlabDrawPlot(cvId, st) {
  const cv = document.getElementById(cvId);
  if (!cv || !st) return;
  const ctx = cv.getContext('2d');
  const W = cv.width, H = cv.height;
  const P = st.presets[st.preset];
  const padL = 62, padR = 14, padT = 14, padB = 40;
  const x0 = padL, y0 = H - padB, x1 = W - padR, y1 = padT;

  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);

  const pts = st.rows.map(r => ({ x: P.x(r), y: P.y(r) })).filter(p => isFinite(p.x) && isFinite(p.y));
  let xmax = pts.length ? Math.max(...pts.map(p => p.x)) * 1.15 : 1;
  let ymax = pts.length ? Math.max(...pts.map(p => p.y)) * 1.15 : 1;
  let xmin = pts.length ? Math.min(0, ...pts.map(p => p.x)) : 0;
  let ymin = pts.length ? Math.min(0, ...pts.map(p => p.y)) : 0;
  if (st.fn) for (let i = 0; i <= 20; i++) {
    let v; try { v = st.fn(xmin + (xmax - xmin) * i / 20); } catch (e) { v = NaN; }
    if (isFinite(v)) { if (v > ymax) ymax = v * 1.05; if (v < ymin) ymin = v * 1.05; }
  }
  if (!(xmax > xmin) || !isFinite(xmax)) xmax = xmin + 1;
  if (!(ymax > ymin) || !isFinite(ymax)) ymax = ymin + 1;

  const X = v => x0 + (v - xmin) / (xmax - xmin) * (x1 - x0);
  const Y = v => y0 - (v - ymin) / (ymax - ymin) * (y0 - y1);

  // Gitter & Achsen
  const xt = _fpmTicks(xmax, 6), yt = _fpmTicks(ymax, 5);
  ctx.font = '10px sans-serif'; ctx.strokeStyle = '#eef2f7'; ctx.lineWidth = 1;
  xt.ticks.forEach(v => {
    if (v < xmin) return;
    ctx.beginPath(); ctx.moveTo(X(v), y0); ctx.lineTo(X(v), y1); ctx.stroke();
    ctx.fillStyle = '#94a3b8'; ctx.textAlign = 'center';
    ctx.fillText(_fpmTickLbl(v, xt.step), X(v), y0 + 14);
  });
  yt.ticks.forEach(v => {
    if (v < ymin) return;
    ctx.beginPath(); ctx.moveTo(x0, Y(v)); ctx.lineTo(x1, Y(v)); ctx.stroke();
    ctx.fillStyle = '#94a3b8'; ctx.textAlign = 'right';
    ctx.fillText(_fpmTickLbl(v, yt.step), x0 - 6, Y(v) + 3);
  });
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.moveTo(x0, y1); ctx.lineTo(x0, y0); ctx.lineTo(x1, y0); ctx.stroke();
  ctx.fillStyle = '#475569'; ctx.font = '700 10px sans-serif'; ctx.textAlign = 'right';
  ctx.fillText(P.xl, x1, y0 + 28);
  ctx.save(); ctx.translate(13, y1 + 2); ctx.rotate(-Math.PI / 2);
  ctx.textAlign = 'right'; ctx.fillText(P.yl, 0, 0); ctx.restore();
  ctx.textAlign = 'left';

  if (!pts.length) {
    ctx.fillStyle = '#94a3b8'; ctx.textAlign = 'center'; ctx.font = '11px sans-serif';
    ctx.fillText('Noch keine Messwerte aufgenommen', (x0 + x1) / 2, (y0 + y1) / 2);
    ctx.textAlign = 'left';
    const fo = document.getElementById(st.fitId);
    if (fo) fo.innerHTML = '<div class="fpm-note">' + P.note + '</div>';
    return;
  }

  // Nutzerfunktion
  if (st.fn) {
    ctx.strokeStyle = '#db2777'; ctx.lineWidth = 1.8; ctx.setLineDash([6, 4]);
    ctx.beginPath();
    let started = false;
    for (let px = x0; px <= x1; px += 2) {
      let yv; try { yv = st.fn(xmin + (px - x0) / (x1 - x0) * (xmax - xmin)); } catch (e) { yv = NaN; }
      if (!isFinite(yv)) { started = false; continue; }
      const py = Y(yv);
      if (py < y1 - 30 || py > y0 + 30) { started = false; continue; }
      started ? ctx.lineTo(px, py) : (ctx.moveTo(px, py), started = true);
    }
    ctx.stroke(); ctx.setLineDash([]);
  }

  // Gruppen
  const groups = [];
  if (P.grp) {
    const map = new Map();
    st.rows.forEach(r => { const k = P.grp(r); if (!map.has(k)) map.set(k, []); map.get(k).push(r); });
    [...map.keys()].sort((a, b) => a - b).forEach(k => groups.push({ key: k, rows: map.get(k) }));
  } else groups.push({ key: null, rows: st.rows });

  const info = [];
  groups.forEach((g, gi) => {
    const col = P.col ? P.col(g.key, gi) : _MLAB_PALETTE[gi % _MLAB_PALETTE.length];
    const gp = g.rows.map(r => ({ x: P.x(r), y: P.y(r) })).filter(p => isFinite(p.x) && isFinite(p.y));

    // Theoriekurve
    if (st.showTheory && P.curveFn) {
      ctx.strokeStyle = '#16a34a'; ctx.lineWidth = 1.2; ctx.setLineDash([3, 3]);
      ctx.beginPath();
      let first = true;
      for (let px = x0; px <= x1; px += 3) {
        const xv = xmin + (px - x0) / (x1 - x0) * (xmax - xmin);
        let yv; try { yv = P.curveFn(xv, g.key); } catch (e) { yv = NaN; }
        const py = Y(yv);
        if (!isFinite(py) || py < y1 - 20 || py > y0 + 20) { first = true; continue; }
        first ? (ctx.moveTo(px, py), first = false) : ctx.lineTo(px, py);
      }
      ctx.stroke(); ctx.setLineDash([]);
    }

    // Ausgleichsgerade
    let fit = null;
    if (!P.curve && gp.length >= 2) {
      fit = st.origin ? _fpmFitOrigin(gp) : _fpmFitLinear(gp);
      if (fit) {
        ctx.strokeStyle = col; ctx.lineWidth = 1.6;
        ctx.beginPath(); ctx.moveTo(X(xmin), Y(fit.k * xmin + fit.b)); ctx.lineTo(X(xmax), Y(fit.k * xmax + fit.b)); ctx.stroke();
      }
    }

    // Messpunkte
    gp.forEach(p => {
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.arc(X(p.x), Y(p.y), 4, 0, 2 * Math.PI); ctx.fill();
      ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.4; ctx.stroke();
    });

    info.push({ key: g.key, col, fit, n: gp.length });
  });

  _mlabRenderFit(st, info, P);
}

function _mlabRenderFit(st, groups, P) {
  const el = document.getElementById(st.fitId);
  if (!el) return;
  if (P.curve) { el.innerHTML = '<div class="fpm-note">' + P.note + '</div>'; return; }

  let html = '';
  groups.forEach(g => {
    if (!g.fit) return;
    const name = g.key === null ? 'alle Messwerte' : P.gl(g.key);
    const eq = 'y = ' + _fpmNum(g.fit.k, Math.abs(g.fit.k) < 1 ? 4 : 3) + '·x' +
      (st.origin ? '' : (g.fit.b >= 0 ? ' + ' : ' − ') + _fpmNum(Math.abs(g.fit.b), 4));
    const erw = P.slope ? ' · erwartet: ' + _fpmNum(P.slope(g.key), Math.abs(P.slope(g.key)) < 1 ? 4 : 3) : '';
    html += `<div class="fpm-fitline">
       <span class="fpm-fitmeta"><span class="fpm-dot" style="background:${g.col}"></span>${name} · ${g.n} Messwerte</span>
       <span class="fpm-fiteq">${eq}</span>
       <span class="fpm-fitmeta">R² = ${_fpmNum(g.fit.r2, 4)}${erw}</span>
     </div>`;
  });

  if (!html) {
    el.innerHTML = '<div class="fpm-note">Mindestens zwei Messwerte je Messreihe nötig.<br>' + P.note + '</div>';
    return;
  }
  // Handlungsorientierter Abschluss: gesuchte Groesse aus der Steigung + Literaturvergleich
  // ergebnis(g0, st) erhaelt die erste Gruppe { key, col, fit, n } und den State.
  if (P.ergebnis && groups[0] && groups[0].fit) {
    html += P.ergebnis(groups[0], st);
  }
  el.innerHTML = html + '<div class="fpm-note" style="border-top:1px solid #e2e8f0;padding-top:7px;margin-top:5px">' + P.note + '</div>';
}

// kleine Helfer fuer den Abschluss-Block
function _mlabBadge(dev) { return dev < 1 ? 'ok' : dev < 5 ? 'mid' : 'no'; }
function _mlabErgebnis(label, wert, einheit, lit, formel) {
  const dev = lit ? Math.abs(wert - lit) / Math.abs(lit) * 100 : null;
  const cls = dev === null ? 'ok' : _mlabBadge(dev);
  return `<div class="fpm-fitline" style="border-top:1px solid #e2e8f0;padding-top:7px;margin-top:5px">
      <span class="fpm-fitmeta">${label}</span>
      <span class="fpm-fiteq">${wert}${einheit ? ' ' + einheit : ''}${lit ? ' &nbsp;·&nbsp; Literatur: ' + lit : ''}</span>
      ${dev !== null ? `<span class="fpm-badge ${cls}">Abweichung ${_fpmNum(dev, 2)} %</span>` : ''}
      ${formel ? `<span class="fpm-fitmeta" style="margin-top:3px">${formel}</span>` : ''}
    </div>`;
}

// ── Funktionsplotter (Theoriefunktion) ─────────────────
function _mlabSetFn(st, str) {
  st.fnAuto = false;
  const err = document.getElementById(st.fnErrId);
  const v = (str || '').trim();
  if (!v) { st.fn = null; if (err) err.textContent = ''; _mlabDrawPlot(st.plotId, st); return; }
  try {
    const f = _fpmMakeFn(v);
    if (typeof f(1) !== 'number') throw new Error('kein Zahlenwert');
    st.fn = f; if (err) err.textContent = '';
  } catch (e) { st.fn = null; if (err) err.textContent = e.message; }
  _mlabDrawPlot(st.plotId, st);
}
function _mlabTheorieFn(st) {
  const P = st.presets[st.preset];
  const term = P.term();
  const inp = document.getElementById(st.fnId);
  if (inp) inp.value = term;
  _mlabSetFn(st, term);
  st.fnAuto = true;
  _mlabRenderTheorie(st, true);
}
function _mlabClearFn(st) {
  const inp = document.getElementById(st.fnId);
  if (inp) inp.value = '';
  _mlabSetFn(st, '');
  _mlabRenderTheorie(st, false);
}
function _mlabRefreshTheorie(st) {
  if (st.fnAuto) {
    const term = st.presets[st.preset].term();
    const inp = document.getElementById(st.fnId);
    if (inp) inp.value = term;
    _mlabSetFn(st, term);
    st.fnAuto = true;
  }
  _mlabRenderTheorie(st, st.fnAuto);
}
function _mlabRenderTheorie(st, eingesetzt) {
  const el = document.getElementById(st.theoId);
  if (!el) return;
  const P = st.presets[st.preset];
  el.innerHTML =
    `<div class="fpm-theo-kopf">Erwarteter Funktionstyp</div>
     <div class="fpm-theo-typ">${P.typ}</div>
     <div class="fpm-theo-form">${P.form}</div>
     <div class="fpm-theo-par">${P.param()}</div>
     ${eingesetzt ? `<div class="fpm-theo-term">eingesetzt: f(x) = ${P.term()}</div>` : ''}
     <div class="fpm-theo-deutung">${P.deutung}</div>`;
}

// ── Standard-Bausteine der Auswertungs-Oberflaeche ─────
// st.pre  = Praefix fuer Element-IDs (z. B. 'glf')
// fns     = { preset, setfn, theo, clear, bool } – Namen der globalen Wiring-Funktionen
// erzeugt die Tab-Leiste zum Umschalten der Achsen
function _mlabTabsHTML(st, presetFnName) {
  return st.presets.map((p, i) =>
    `<button class="fpm-tab${i === st.preset ? ' on' : ''}" id="${st.pre}Tab${i}" onclick="${presetFnName}(${i})">${p.tab}</button>`).join('');
}
// schaltet Preset um (im konkreten Sim-Modul aufgerufen)
function _mlabSetPreset(st, i) {
  st.preset = i;
  for (let k = 0; k < st.presets.length; k++) document.getElementById(st.pre + 'Tab' + k)?.classList.toggle('on', k === i);
  _mlabRefreshTheorie(st);
  _mlabDrawPlot(st.plotId, st);
}
// rechter Auswertungsblock (Fit + Funktionsplotter + Theoriebox)
function _mlabAuswertungHTML(st, fns) {
  return `<div class="fpm-tabs">${_mlabTabsHTML(st, fns.preset)}</div>
    <div class="fpm-grid2">
      <canvas id="${st.plotId}" width="470" height="330" class="phys-chart-cv"></canvas>
      <div>
        <div class="fpm-fit" id="${st.fitId}"></div>
        <div class="fpm-label" style="margin-top:10px">Funktion plotten</div>
        <input type="text" id="${st.fnId}" class="fpm-input" placeholder="z. B. 2*x" spellcheck="false"
          oninput="${fns.setfn}(this.value)">
        <div class="fpm-err" id="${st.fnErrId}"></div>
        <div class="sim-btn-row" style="padding:2px 0 4px">
          <button class="sim-btn primary" onclick="${fns.theo}()">ƒ Theoriefunktion</button>
          <button class="sim-btn" onclick="${fns.clear}()">Feld leeren</button>
        </div>
        <div class="fpm-theo" id="${st.theoId}"></div>
        <div class="fpm-note">Erlaubt: x, pi, + − * / ^, sqrt(), sin(), cos(), abs(), exp(), ln(). Malpunkt immer schreiben.</div>
        <label class="fpm-check"><input type="checkbox"${st.origin ? ' checked' : ''} onchange="${fns.bool}('origin',this.checked)">
          Ausgleichsgerade durch den Ursprung</label>
        <label class="fpm-check"><input type="checkbox" onchange="${fns.bool}('showTheory',this.checked)">
          Theoriekurve einblenden</label>
      </div>
    </div>`;
}

// ═══════════════════════════════════════════════════════
// 1.2 GLEICHFOERMIGE BEWEGUNG – handlungsorientiert
// Fahrbahn mit Lichtschranken. Schueler waehlt v, misst die
// Durchgangszeiten -> Weg-Zeit-Tabelle -> Ursprungsgerade,
// Steigung = gefahrene Geschwindigkeit. s ~ t.
// ═══════════════════════════════════════════════════════

const _GLF_MARKS = [1.5, 3.0, 4.5, 6.0, 7.5, 9.0];   // Lichtschranken in m (10-m-Fahrbahn)
let _glf = null;

const _GLF_PRESETS = [
  { tab: 't → s', xl: 't in s', yl: 's in m', x: r => r.t, y: r => r.s, grp: r => r.v,
    gl: k => 'v = ' + _fpmNum(+k, 1) + ' m/s', slope: k => +k,
    col: (k, i) => _MLAB_PALETTE[i % _MLAB_PALETTE.length],
    curveFn: (xv, k) => k * xv,
    note: 'Ursprungsgerade ⇒ s ~ t. Die Steigung jeder Geraden ist die gefahrene Geschwindigkeit v = s/t. Steiler = schneller. Bei gleichförmiger Bewegung ist v konstant.',
    typ: 'proportionale Funktion (Ursprungsgerade)', form: 's(t) = v · t',
    param: () => 'Steigung = v = ' + _fpmNum(_glf.v, 1) + ' m/s (aktuell gewählt)',
    term: () => _glf.v.toString() + '*x',
    deutung: 'Weg proportional zur Zeit: In gleichen Zeiten wird immer die gleiche Strecke zurückgelegt. Die Steigung der Geraden ist die Geschwindigkeit.',
    ergebnis: (g0) => _mlabErgebnis('Geschwindigkeit v = Steigung der Ausgleichsgeraden',
      _fpmNum(g0.fit.k, 2), 'm/s', _fpmNum(g0.key, 2), 's = v·t  ⇒  v = s/t') }
];

function _glfInit() {
  _glf = {
    v: 4.0, dispS: 0, flash: 0,
    rows: [], nextId: 1, preset: 0, fn: null, fnAuto: false, origin: true, showTheory: false,
    pre: 'glf', plotId: 'glfPlot', fitId: 'glfFit', fnId: 'glfFn', fnErrId: 'glfErr', theoId: 'glfTheo',
    presets: _GLF_PRESETS
  };
}

function _glfHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim glf-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🚗 Gleichförmige Bewegung – das Weg-Zeit-Gesetz selbst messen</h3>
    <div class="fpm-grid">
      <div>
        <canvas id="glfAnim" width="420" height="240" class="phys-anim-cv"></canvas>
        <div class="phys-ctrl" style="margin-top:8px">
          <span class="phys-ctrl-label">Geschwindigkeit v: <b id="glfVLbl">4,0 m/s</b></span>
          <input type="range" id="glfV" min="1" max="9" step="0.5" value="4"
            oninput="_glfSetV(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="fpm-note" style="margin-top:6px">Wähle eine Geschwindigkeit und schicke den Wagen durch die 6 Lichtschranken. Jede Schranke stoppt automatisch die Zeit. Danach eine <b>andere</b> Geschwindigkeit messen und vergleichen.</div>
      </div>
      <div>
        <div class="fpm-label">Messung</div>
        <div class="sim-btn-row">
          <button class="sim-btn primary" onclick="_glfMessen()">⏱ Lichtschranken-Messfahrt</button>
          <button class="sim-btn" onclick="_glfDemo()">📋 Beispielmessreihe</button>
          <button class="sim-btn" onclick="_glfClear()">🗑 Tabelle leeren</button>
        </div>
        <div class="fpm-tablewrap">
          <table class="sim-table">
            <thead><tr><th>v (m/s)</th><th>s (m)</th><th>t (s)</th><th></th></tr></thead>
            <tbody id="glfTbody"></tbody>
          </table>
          <div class="fpm-empty" id="glfEmpty">Noch keine Messwerte.<br>Geschwindigkeit wählen → Messfahrt starten.</div>
        </div>
      </div>
    </div>
    <div class="fpm-label" style="margin-top:12px">Auswertung – trage s über t auf. Liegen die Punkte auf einer Ursprungsgeraden?</div>
    ${_mlabAuswertungHTML(_glf, { preset: '_glfSetPreset', setfn: '_glfSetFn', theo: '_glfTheorieFn', clear: '_glfClearFn', bool: '_glfSetBool' })}
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      <b>s = v · t</b> &nbsp;⇒&nbsp; die Steigung der s-t-Geraden <i>ist</i> die Geschwindigkeit &nbsp;|&nbsp; nur eine Größe verändern
    </p>
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _glfSetV(v) {
  _glf.v = +v;
  const el = document.getElementById('glfVLbl'); if (el) el.textContent = _fpmNum(+v, 1) + ' m/s';
  _mlabRefreshTheorie(_glf);
}
function _glfMessen() {
  const v = _glf.v;
  _GLF_MARKS.forEach(s => {
    // Stoppuhr-Ablesung: wahre Zeit s/v, gerundet auf 0,01 s, mit kleiner Reaktionsstreuung
    const t = (s / v) * (1 + (Math.random() - 0.5) * 0.012);
    _glfAddRow(v, s, Math.round(t * 100) / 100);
  });
  _glf.flash = 1;
}
function _glfDemo() {
  [3.0, 5.0, 7.0].forEach(v => _GLF_MARKS.forEach(s => {
    const t = (s / v) * (1 + (Math.random() - 0.5) * 0.012);
    _glf.rows.push({ id: _glf.nextId++, v, s, t: Math.round(t * 100) / 100 });
  }));
  _glfRenderTable(); _mlabDrawPlot('glfPlot', _glf);
}
function _glfAddRow(v, s, t) {
  _glf.rows.push({ id: _glf.nextId++, v, s, t });
  _glfRenderTable(); _mlabDrawPlot('glfPlot', _glf);
}
function _glfDelRow(id) { _glf.rows = _glf.rows.filter(r => r.id !== id); _glfRenderTable(); _mlabDrawPlot('glfPlot', _glf); }
function _glfClear() {
  if (_glf.rows.length && !confirm('Alle ' + _glf.rows.length + ' Messwerte löschen?')) return;
  _glf.rows = []; _glfRenderTable(); _mlabDrawPlot('glfPlot', _glf);
}
function _glfColV(v) { const i = [3, 4, 5, 6, 7].indexOf(Math.round(v)); return _MLAB_PALETTE[(i < 0 ? Math.round(v) : i) % _MLAB_PALETTE.length]; }
function _glfRenderTable() {
  const tb = document.getElementById('glfTbody'); if (!tb) return;
  const empty = document.getElementById('glfEmpty');
  if (empty) empty.style.display = _glf.rows.length ? 'none' : 'block';
  tb.innerHTML = _glf.rows.map(r =>
    `<tr><td><span class="fpm-dot" style="background:${_glfColV(r.v)}"></span>${_fpmNum(r.v, 1)}</td>
       <td>${_fpmNum(r.s, 1)}</td><td><b>${_fpmNum(r.t, 2)}</b></td>
       <td class="fpm-del" onclick="_glfDelRow(${r.id})" title="löschen">✕</td></tr>`).join('');
}

// ── Wiring zum Framework ───────────────────────────────
function _glfSetPreset(i) { _mlabSetPreset(_glf, i); }
function _glfSetFn(s) { _mlabSetFn(_glf, s); }
function _glfTheorieFn() { _mlabTheorieFn(_glf); }
function _glfClearFn() { _mlabClearFn(_glf); }
function _glfSetBool(k, v) { _glf[k] = v; _mlabDrawPlot('glfPlot', _glf); }

// ── Animation ──────────────────────────────────────────
function _glfUpdate(dt) {
  if (!_glf) return;
  _glf.dispS += _glf.v * dt;
  if (_glf.dispS > 10) _glf.dispS -= 10;
  _glf.flash = Math.max(0, _glf.flash - dt * 1.5);
}
function _glfDraw(ctx, cv) {
  if (!_glf) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#f0f9ff'; ctx.fillRect(0, 0, W, H);
  const road = H - 60, mL = 30, mR = W - 20, span = mR - mL;
  const sx = s => mL + s / 10 * span;
  // Fahrbahn
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(mL, road, span, 8);
  // Lichtschranken
  _GLF_MARKS.forEach(s => {
    ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(sx(s), road - 46); ctx.lineTo(sx(s), road); ctx.stroke();
    ctx.fillStyle = '#94a3b8'; ctx.font = '9px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText(_fpmNum(s, 1), sx(s), road + 22);
  });
  ctx.fillStyle = '#64748b'; ctx.font = '700 10px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText('Lichtschranken bei s (m):', mL, road + 40);
  // Wagen
  const cx = sx(_glf.dispS);
  ctx.fillStyle = _glf.flash > 0.3 ? '#f97316' : '#7c3aed';
  const bw = 34, bh = 18;
  ctx.beginPath(); ctx.roundRect ? ctx.roundRect(cx - bw / 2, road - bh, bw, bh, 4) : ctx.rect(cx - bw / 2, road - bh, bw, bh); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.arc(cx - 9, road, 4, 0, 2 * Math.PI); ctx.arc(cx + 9, road, 4, 0, 2 * Math.PI); ctx.fill();
  // Infozeile
  ctx.fillStyle = '#1e293b'; ctx.font = '700 12px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText('v = ' + _fpmNum(_glf.v, 1) + ' m/s  (konstant)', mL, 22);
  ctx.fillStyle = '#7c3aed'; ctx.font = '11px sans-serif';
  ctx.fillText('s = ' + _fpmNum(_glf.dispS, 2) + ' m', mL, 40);
}

// ═══════════════════════════════════════════════════════
// 1.3 BESCHLEUNIGTE BEWEGUNG – handlungsorientiert
// Wagen startet aus der Ruhe, konstante Beschleunigung a.
// Lichtschranken messen an jeder Marke Zeit t und Momentan-
// geschwindigkeit v.  v-t-Gerade: Steigung = a.  s-t²-Gerade:
// Steigung = a/2.  Parabel s(t) linearisieren.
// ═══════════════════════════════════════════════════════

const _BSL_MARKS = [0.5, 1.0, 2.0, 3.0, 4.5, 6.0];   // Marken in m
let _bsl = null;

const _BSL_PRESETS = [
  { tab: 't → v', xl: 't in s', yl: 'v in m/s', x: r => r.t, y: r => r.v, grp: r => r.a,
    gl: k => 'a = ' + _fpmNum(+k, 1) + ' m/s²', slope: k => +k,
    curveFn: (xv, k) => k * xv,
    note: 'Ursprungsgerade ⇒ v ~ t. Die Steigung ist direkt die Beschleunigung a = Δv/Δt. Aus der Ruhe heraus gilt v = a·t.',
    typ: 'proportionale Funktion (Ursprungsgerade)', form: 'v(t) = a · t',
    param: () => 'Steigung = a = ' + _fpmNum(_bsl.a, 1) + ' m/s² (aktuell gewählt)',
    term: () => _bsl.a.toString() + '*x',
    deutung: 'Die Geschwindigkeit wächst gleichmäßig mit der Zeit. Die Steigung der v-t-Geraden ist die Beschleunigung.',
    ergebnis: (g0) => _mlabErgebnis('Beschleunigung a = Steigung der v-t-Geraden',
      _fpmNum(g0.fit.k, 2), 'm/s²', _fpmNum(g0.key, 2), 'v = a·t  ⇒  a = Δv/Δt') },
  { tab: 't → s', xl: 't in s', yl: 's in m', x: r => r.t, y: r => r.s, grp: r => r.a,
    gl: k => 'a = ' + _fpmNum(+k, 1) + ' m/s²', curve: true, col: (k, i) => _MLAB_PALETTE[i % _MLAB_PALETTE.length],
    curveFn: (xv, k) => 0.5 * k * xv * xv,
    note: 'Keine Gerade, sondern eine Parabel: s ~ t². Verdoppelst du die Zeit, vervierfacht sich der Weg. Aus einer Kurve liest man schlecht ab – quadriere t und wechsle zur Auftragung t² → s.',
    typ: 'quadratische Funktion (Parabel)', form: 's(t) = ½ · a · t²',
    param: () => 'a = ' + _fpmNum(_bsl.a, 1) + ' m/s²',
    term: () => '0.5*' + _bsl.a.toString() + '*x^2',
    deutung: 'Der Weg wächst quadratisch mit der Zeit – typisch für gleichmäßige Beschleunigung.' },
  { tab: 't² → s', xl: 't² in s²', yl: 's in m', x: r => r.t * r.t, y: r => r.s, grp: r => r.a,
    gl: k => 'a = ' + _fpmNum(+k, 1) + ' m/s²', slope: k => +k / 2,
    curveFn: (xv, k) => 0.5 * k * xv,
    note: 'Jetzt liegen die Punkte auf einer Ursprungsgeraden ⇒ s ~ t². Die Steigung ist a/2, also a = 2 · Steigung.',
    typ: 'proportionale Funktion (Ursprungsgerade)', form: 's(t²) = (a/2) · t²',
    param: () => 'Steigung = a/2 = ' + _fpmNum(_bsl.a / 2, 2) + ' m/s²',
    term: () => (_bsl.a / 2).toString() + '*x',
    deutung: 'Durch das Quadrieren der Zeit wird aus der Parabel eine Gerade durch den Ursprung. Die Steigung ist die halbe Beschleunigung.',
    ergebnis: (g0) => _mlabErgebnis('Beschleunigung a = 2 × Steigung',
      _fpmNum(2 * g0.fit.k, 2), 'm/s²', _fpmNum(g0.key, 2), 's = ½·a·t²  ⇒  a = 2·(s/t²)') }
];

function _bslInit() {
  _bsl = {
    a: 2.0, dispT: 0, flash: 0,
    rows: [], nextId: 1, preset: 0, fn: null, fnAuto: false, origin: true, showTheory: false,
    pre: 'bsl', plotId: 'bslPlot', fitId: 'bslFit', fnId: 'bslFn', fnErrId: 'bslErr', theoId: 'bslTheo',
    presets: _BSL_PRESETS
  };
}

function _bslHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim bsl-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🚀 Beschleunigte Bewegung – v = a·t und s = ½a·t² messen</h3>
    <div class="fpm-grid">
      <div>
        <canvas id="bslAnim" width="420" height="240" class="phys-anim-cv"></canvas>
        <div class="phys-ctrl" style="margin-top:8px">
          <span class="phys-ctrl-label">Beschleunigung a: <b id="bslALbl">2,0 m/s²</b></span>
          <input type="range" id="bslA" min="0.5" max="8" step="0.5" value="2"
            oninput="_bslSetA(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="fpm-note" style="margin-top:6px">Der Wagen startet aus der Ruhe. Jede Lichtschranke misst die Zeit <b>und</b> die Momentangeschwindigkeit. Danach mit einer <b>anderen</b> Beschleunigung wiederholen.</div>
      </div>
      <div>
        <div class="fpm-label">Messung</div>
        <div class="sim-btn-row">
          <button class="sim-btn primary" onclick="_bslMessen()">⏱ Lichtschranken-Messfahrt</button>
          <button class="sim-btn" onclick="_bslDemo()">📋 Beispielmessreihe</button>
          <button class="sim-btn" onclick="_bslClear()">🗑 Tabelle leeren</button>
        </div>
        <div class="fpm-tablewrap">
          <table class="sim-table">
            <thead><tr><th>a (m/s²)</th><th>s (m)</th><th>t (s)</th><th>v (m/s)</th><th></th></tr></thead>
            <tbody id="bslTbody"></tbody>
          </table>
          <div class="fpm-empty" id="bslEmpty">Noch keine Messwerte.<br>Beschleunigung wählen → Messfahrt starten.</div>
        </div>
      </div>
    </div>
    <div class="fpm-label" style="margin-top:12px">Auswertung – finde die Auftragung, bei der die Punkte auf einer Ursprungsgeraden liegen</div>
    ${_mlabAuswertungHTML(_bsl, { preset: '_bslSetPreset', setfn: '_bslSetFn', theo: '_bslTheorieFn', clear: '_bslClearFn', bool: '_bslSetBool' })}
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      <b>v = a·t</b> (Gerade, Steigung a) &nbsp;|&nbsp; <b>s = ½a·t²</b> (Parabel → Gerade nach t²)
    </p>
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _bslSetA(v) {
  _bsl.a = +v;
  const el = document.getElementById('bslALbl'); if (el) el.textContent = _fpmNum(+v, 1) + ' m/s²';
  _mlabRefreshTheorie(_bsl);
}
function _bslMessRow(a, s) {
  const tTrue = Math.sqrt(2 * s / a), vTrue = a * tTrue;
  const t = tTrue * (1 + (Math.random() - 0.5) * 0.012);
  const v = vTrue * (1 + (Math.random() - 0.5) * 0.02);
  return { a, s, t: Math.round(t * 100) / 100, v: Math.round(v * 10) / 10 };
}
function _bslMessen() {
  _BSL_MARKS.forEach(s => { const r = _bslMessRow(_bsl.a, s); _bslAddRow(r.a, r.s, r.t, r.v); });
  _bsl.flash = 1;
}
function _bslDemo() {
  [1.0, 2.0, 4.0].forEach(a => _BSL_MARKS.forEach(s => {
    const r = _bslMessRow(a, s); _bsl.rows.push({ id: _bsl.nextId++, a: r.a, s: r.s, t: r.t, v: r.v });
  }));
  _bslRenderTable(); _mlabDrawPlot('bslPlot', _bsl);
}
function _bslAddRow(a, s, t, v) {
  _bsl.rows.push({ id: _bsl.nextId++, a, s, t, v });
  _bslRenderTable(); _mlabDrawPlot('bslPlot', _bsl);
}
function _bslDelRow(id) { _bsl.rows = _bsl.rows.filter(r => r.id !== id); _bslRenderTable(); _mlabDrawPlot('bslPlot', _bsl); }
function _bslClear() {
  if (_bsl.rows.length && !confirm('Alle ' + _bsl.rows.length + ' Messwerte löschen?')) return;
  _bsl.rows = []; _bslRenderTable(); _mlabDrawPlot('bslPlot', _bsl);
}
function _bslColA(a) { const i = [1, 2, 3, 4, 5, 6, 7, 8].indexOf(Math.round(a)); return _MLAB_PALETTE[(i < 0 ? 0 : i) % _MLAB_PALETTE.length]; }
function _bslRenderTable() {
  const tb = document.getElementById('bslTbody'); if (!tb) return;
  const empty = document.getElementById('bslEmpty');
  if (empty) empty.style.display = _bsl.rows.length ? 'none' : 'block';
  tb.innerHTML = _bsl.rows.map(r =>
    `<tr><td><span class="fpm-dot" style="background:${_bslColA(r.a)}"></span>${_fpmNum(r.a, 1)}</td>
       <td>${_fpmNum(r.s, 1)}</td><td><b>${_fpmNum(r.t, 2)}</b></td><td>${_fpmNum(r.v, 1)}</td>
       <td class="fpm-del" onclick="_bslDelRow(${r.id})" title="löschen">✕</td></tr>`).join('');
}

// ── Wiring ─────────────────────────────────────────────
function _bslSetPreset(i) { _mlabSetPreset(_bsl, i); }
function _bslSetFn(s) { _mlabSetFn(_bsl, s); }
function _bslTheorieFn() { _mlabTheorieFn(_bsl); }
function _bslClearFn() { _mlabClearFn(_bsl); }
function _bslSetBool(k, v) { _bsl[k] = v; _mlabDrawPlot('bslPlot', _bsl); }

// ── Animation ──────────────────────────────────────────
function _bslUpdate(dt) {
  if (!_bsl) return;
  _bsl.dispT += dt;
  const s = 0.5 * _bsl.a * _bsl.dispT * _bsl.dispT;
  if (s > 6.5) _bsl.dispT = 0;
  _bsl.flash = Math.max(0, _bsl.flash - dt * 1.5);
}
function _bslDraw(ctx, cv) {
  if (!_bsl) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#f0f9ff'; ctx.fillRect(0, 0, W, H);
  const road = H - 60, mL = 30, mR = W - 20, span = mR - mL, SMAX = 6.5;
  const sx = s => mL + s / SMAX * span;
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(mL, road, span, 8);
  _BSL_MARKS.forEach(s => {
    ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(sx(s), road - 46); ctx.lineTo(sx(s), road); ctx.stroke();
    ctx.fillStyle = '#94a3b8'; ctx.font = '9px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText(_fpmNum(s, 1), sx(s), road + 22);
  });
  ctx.fillStyle = '#64748b'; ctx.font = '700 10px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText('Lichtschranken bei s (m):', mL, road + 40);
  const sNow = 0.5 * _bsl.a * _bsl.dispT * _bsl.dispT, vNow = _bsl.a * _bsl.dispT;
  const cx = sx(Math.min(sNow, SMAX));
  ctx.fillStyle = _bsl.flash > 0.3 ? '#f97316' : '#7c3aed';
  const bw = 34, bh = 18;
  ctx.beginPath(); ctx.roundRect ? ctx.roundRect(cx - bw / 2, road - bh, bw, bh, 4) : ctx.rect(cx - bw / 2, road - bh, bw, bh); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.arc(cx - 9, road, 4, 0, 2 * Math.PI); ctx.arc(cx + 9, road, 4, 0, 2 * Math.PI); ctx.fill();
  // Geschwindigkeitspfeil
  ctx.strokeStyle = '#16a34a'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(cx, road - bh - 6); ctx.lineTo(cx + Math.min(70, vNow * 8), road - bh - 6); ctx.stroke();
  ctx.fillStyle = '#1e293b'; ctx.font = '700 12px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText('a = ' + _fpmNum(_bsl.a, 1) + ' m/s²', mL, 22);
  ctx.fillStyle = '#16a34a'; ctx.font = '11px sans-serif';
  ctx.fillText('v = ' + _fpmNum(vNow, 1) + ' m/s', mL, 40);
}

// ═══════════════════════════════════════════════════════
// 1.1 MERKMALE VON SCHWINGUNGEN – handlungsorientiert
// Grundlage: Handreichung "Schwingungen" (Jg. 12), Abschnitt 1.1.1
// Oszillator waehlen, y-t-Diagramm aufnehmen, T = Δt/n messen,
// Amplitude/Elongation ablesen, ungedaempft vs. gedaempft,
// Scheitelwerte -> ln(ŷ)-Gerade -> Daempfung δ + Halbwertszeit.
// Darunter ein Arbeitsblatt (10-teilige Struktur) zum Ausfuellen.
// ═══════════════════════════════════════════════════════

const _SWG_WIN = 12;                       // Zeitfenster des Diagramms in s
const _SWG_DELTA = { aus: 0, schwach: 0.12, stark: 0.30 };  // Daempfungskonstante δ in 1/s
const _SWG_OSZ = [
  { k: 'fed',  n: 'Federpendel',   ic: '🪀' },
  { k: 'fad',  n: 'Fadenpendel',   ic: '🕰' },
  { k: 'rohr', n: 'Wassersäule (U-Rohr)', ic: '🧪' },
  { k: 'hem',  n: 'Hemmungspendel', ic: '⚙️' }
];
let _swg = null;

const _SWG_PRESETS = [
  { tab: 't → ŷ', xl: 't in s', yl: 'ŷ in cm', x: r => r.t, y: r => r.yhat, grp: null,
    curve: true, col: () => '#7c3aed',
    curveFn: (t) => _swg.amp0 * Math.exp(-_swgDelta() * t),
    note: 'Trägst du die Scheitelwerte (Amplituden) gegen die Zeit auf, liegen sie bei Dämpfung auf einer fallenden Kurve – der Einhüllenden ŷ(t) = ŷ₀·e^(−δ·t). Ohne Dämpfung bleibt ŷ konstant (waagerecht). Aus einer Kurve liest man δ schlecht ab – logarithmiere ŷ und wechsle zur Auftragung t → ln(ŷ).',
    typ: 'Exponentialfunktion (Einhüllende)', form: 'ŷ(t) = ŷ₀ · e^(−δ·t)',
    param: () => 'ŷ₀ = ' + _fpmNum(_swg.amp0, 1) + ' cm, δ = ' + _fpmNum(_swgDelta(), 2) + ' 1/s',
    term: () => _swg.amp0.toString() + '*exp(-' + _swgDelta() + '*x)',
    deutung: 'Die Amplitude nimmt bei Dämpfung exponentiell ab. Die grüne Einhüllende verbindet die Scheitel.' },
  { tab: 't → ln(ŷ)', xl: 't in s', yl: 'ln(ŷ / cm)', x: r => r.t, y: r => Math.log(r.yhat), grp: null,
    slope: () => -_swgDelta(), col: () => '#0284c7',
    curveFn: (t) => Math.log(_swg.amp0) - _swgDelta() * t,
    note: 'Jetzt liegen die Punkte auf einer Geraden ⇒ ln(ŷ) = ln(ŷ₀) − δ·t. Die Steigung ist −δ. Bei einer ungedämpften Schwingung ist die Gerade waagerecht (δ ≈ 0).',
    typ: 'lineare Funktion', form: 'ln(ŷ) = ln(ŷ₀) − δ · t',
    param: () => 'Steigung = −δ = ' + _fpmNum(-_swgDelta(), 2) + ' 1/s',
    term: () => Math.log(_swg.amp0).toFixed(3) + '-' + _swgDelta() + '*x',
    deutung: 'Durch das Logarithmieren wird aus der Exponentialkurve eine Gerade. Die Steigung liefert die Dämpfungskonstante δ.',
    ergebnis: (g0) => {
      const d = -g0.fit.k;
      if (d < 0.01) return _mlabErgebnis('Dämpfungskonstante δ = −Steigung', '≈ 0  (ungedämpft)', '', null,
        'Die Amplitude bleibt konstant – keine Dämpfung.');
      const th = Math.log(2) / d;
      return _mlabErgebnis('Dämpfungskonstante δ = −Steigung', _fpmNum(d, 3), '1/s', _fpmNum(_swgDelta(), 3),
        'ŷ(t) = ŷ₀·e^(−δt)  ⇒  ln ŷ = ln ŷ₀ − δ·t') +
        _mlabErgebnis('Halbwertszeit t½ = ln 2 / δ', _fpmNum(th, 2), 's', null, 'Nach t½ ist die Amplitude halbiert.');
    } }
];

function _swgInit() {
  _swg = {
    osz: 'fed', amp0: 6, T: 2.0, daempf: 'schwach',
    t: 0, running: true, cursor: 3.0,
    sw: { state: 'idle', t0: 0, n: 0, elapsed: 0, T: null },
    rows: [], nextId: 1,
    preset: 0, fn: null, fnAuto: false, origin: false, showTheory: false,
    pre: 'swg', plotId: 'swgPlot', fitId: 'swgFit', fnId: 'swgFn', fnErrId: 'swgErr', theoId: 'swgTheo',
    presets: _SWG_PRESETS
  };
}

// ── Physik ─────────────────────────────────────────────
function _swgDelta() { return _SWG_DELTA[_swg.daempf]; }
function _swgYmax(t) { return _swg.amp0 * Math.exp(-_swgDelta() * t); }
function _swgY(t) {
  let y = _swgYmax(t) * Math.cos(2 * Math.PI * t / _swg.T);
  if (_swg.osz === 'hem' && y < 0) y *= 0.6;   // Unsymmetrie des Hemmungspendels (Abb. 5)
  return y;
}
function _swgPeaks(n) {
  const out = [];
  for (let k = 0; k < n; k++) { const t = k * _swg.T; if (t > _SWG_WIN) break; out.push({ t, yhat: _swgYmax(t) }); }
  return out;
}

// ── Oberflaeche ────────────────────────────────────────
function _swgHTML() {
  const oszBtns = _SWG_OSZ.map(o =>
    `<button class="fpm-spring${o.k === _swg.osz ? ' on' : ''}" id="swgOsz_${o.k}" onclick="_swgSetOsz('${o.k}')" style="flex:1 1 60px">
       <span class="fpm-spring-n">${o.ic} ${o.n}</span></button>`).join('');
  const dmpBtns = [['aus', 'ungedämpft'], ['schwach', 'schwach gedämpft'], ['stark', 'stark gedämpft']].map(d =>
    `<button class="fpm-tab${d[0] === _swg.daempf ? ' on' : ''}" id="swgDmp_${d[0]}" onclick="_swgSetDmp('${d[0]}')">${d[1]}</button>`).join('');

  return `<div class="sim-box sim-box-wide fpm-sim swg-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">〰️ Merkmale von Schwingungen – T, f, Amplitude und Dämpfung selbst messen</h3>

    <div class="fpm-grid">
      <div>
        <canvas id="swgAnim" width="420" height="200" class="phys-anim-cv"></canvas>
        <div class="fpm-label">Oszillator wählen (schwingungsfähiges System)</div>
        <div class="fpm-springs">${oszBtns}</div>
        <div class="phys-ctrl" style="margin-top:8px">
          <span class="phys-ctrl-label">Amplitude ŷ₀: <b id="swgALbl">6,0 cm</b></span>
          <input type="range" id="swgA" min="2" max="9" step="0.5" value="6" oninput="_swgSetA(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="phys-ctrl">
          <span class="phys-ctrl-label">Periodendauer T (Einstellung): <b id="swgTLbl">2,0 s</b></span>
          <input type="range" id="swgT" min="1" max="4" step="0.25" value="2" oninput="_swgSetT(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="fpm-label" style="margin-top:8px">Dämpfung</div>
        <div class="fpm-tabs">${dmpBtns}</div>
      </div>

      <div>
        <canvas id="swgGraph" width="420" height="210" class="phys-chart-cv"></canvas>
        <div class="phys-ctrl" style="margin-top:6px">
          <span class="phys-ctrl-label">Ablese-Cursor bei t = <b id="swgCurLbl">3,00 s</b> → y = <b id="swgCurY" style="color:#db2777">—</b></span>
          <input type="range" id="swgCur" min="0" max="12" step="0.05" value="3" oninput="_swgSetCursor(this.value)" style="width:100%;accent-color:#db2777">
        </div>
        <div class="fpm-label" style="margin-top:6px">Periodendauer messen:  T = Δt / n</div>
        <div class="fpm-readout">
          <div class="fpm-ro"><span class="fpm-ro-k">Perioden n</span><span class="fpm-ro-v" id="swgN">0</span><span class="fpm-ro-u">gezählt</span></div>
          <div class="fpm-ro"><span class="fpm-ro-k">Zeit Δt</span><span class="fpm-ro-v" id="swgDt">0,00</span><span class="fpm-ro-u">s</span></div>
          <div class="fpm-ro"><span class="fpm-ro-k">T = Δt/n · f = 1/T</span><span class="fpm-ro-v" id="swgTf">—</span><span class="fpm-ro-u"></span></div>
        </div>
        <div class="sim-btn-row">
          <button class="sim-btn primary" id="swgStartBtn" onclick="_swgSWStart()">▶ Stoppuhr start</button>
          <button class="sim-btn" id="swgStopBtn" onclick="_swgSWStop()" disabled>■ Stopp</button>
        </div>
      </div>
    </div>

    <div class="fpm-label" style="margin-top:12px">Scheitelwerte (Amplituden) aufnehmen – zum Untersuchen der Dämpfung</div>
    <div class="sim-btn-row">
      <button class="sim-btn primary" onclick="_swgScheitelAuto()">📈 Scheitelwerte aufnehmen</button>
      <button class="sim-btn" onclick="_swgClear()">🗑 Tabelle leeren</button>
    </div>
    <div class="fpm-grid2" style="margin-top:8px">
      <div class="fpm-tablewrap" style="max-height:150px">
        <table class="sim-table">
          <thead><tr><th>k</th><th>t (s)</th><th>ŷ (cm)</th><th>ln(ŷ)</th><th></th></tr></thead>
          <tbody id="swgTbody"></tbody>
        </table>
        <div class="fpm-empty" id="swgEmpty">Noch keine Scheitelwerte.<br>Erst Dämpfung wählen, dann „Scheitelwerte aufnehmen".</div>
      </div>
      <div class="fpm-note">Ein <b>Scheitelwert</b> ist die größte Auslenkung einer Schwingung (die Amplitude). Bei Dämpfung wird jeder Scheitel kleiner als der vorige. Nimm die Werte auf und finde unten heraus, <b>wie</b> die Amplitude abnimmt.</div>
    </div>

    <div class="fpm-label" style="margin-top:12px">Auswertung – wie hängt die Amplitude ŷ von der Zeit ab?</div>
    ${_mlabAuswertungHTML(_swg, { preset: '_swgSetPreset', setfn: '_swgSetFn', theo: '_swgTheorieFn', clear: '_swgClearFn', bool: '_swgSetBool' })}

    ${_swgArbeitsblattHTML()}

    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      <b>T = Δt/n</b>, <b>f = 1/T</b> (1 Hz = 1 s⁻¹) &nbsp;|&nbsp; ungedämpft: ŷ konstant &nbsp;·&nbsp; gedämpft: ŷ = ŷ₀·e^(−δt)
    </p>
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _swgSetOsz(k) {
  _swg.osz = k;
  _SWG_OSZ.forEach(o => document.getElementById('swgOsz_' + o.k)?.classList.toggle('on', o.k === k));
  _swgSWReset();
}
function _swgSetDmp(d) {
  _swg.daempf = d;
  ['aus', 'schwach', 'stark'].forEach(x => document.getElementById('swgDmp_' + x)?.classList.toggle('on', x === d));
  _mlabRefreshTheorie(_swg); _mlabDrawPlot('swgPlot', _swg);
}
function _swgSetA(v) { _swg.amp0 = +v; const el = document.getElementById('swgALbl'); if (el) el.textContent = _fpmNum(+v, 1) + ' cm'; _mlabRefreshTheorie(_swg); }
function _swgSetT(v) { _swg.T = +v; const el = document.getElementById('swgTLbl'); if (el) el.textContent = _fpmNum(+v, 2) + ' s'; _swgSWReset(); }
function _swgSetCursor(v) {
  _swg.cursor = +v;
  const l = document.getElementById('swgCurLbl'); if (l) l.textContent = _fpmNum(+v, 2) + ' s';
  const y = document.getElementById('swgCurY'); if (y) y.textContent = _fpmNum(_swgY(+v), 2) + ' cm';
}

// Stoppuhr
function _swgSWReset() {
  _swg.sw = { state: 'idle', t0: 0, n: 0, elapsed: 0, T: null };
  _swgSWRender();
}
function _swgSWStart() { _swg.sw = { state: 'running', t0: _swg.t, n: 0, elapsed: 0, T: null }; _swgSWRender(); }
function _swgSWStop() {
  const sw = _swg.sw; if (sw.state !== 'running') return;
  sw.state = 'stopped';
  sw.elapsed = Math.round((_swg.t - sw.t0) * 100) / 100;
  sw.n = Math.floor((_swg.t - sw.t0) / _swg.T + 1e-9);
  sw.T = sw.n > 0 ? sw.elapsed / sw.n : null;
  _swgSWRender();
}
function _swgSWRender() {
  const sw = _swg.sw;
  const running = sw.state === 'running';
  if (running) { sw.elapsed = _swg.t - sw.t0; sw.n = Math.floor(sw.elapsed / _swg.T + 1e-9); }
  const nEl = document.getElementById('swgN'); if (nEl) nEl.textContent = sw.n;
  const dtEl = document.getElementById('swgDt'); if (dtEl) dtEl.textContent = _fpmNum(sw.elapsed, 2);
  const tfEl = document.getElementById('swgTf');
  if (tfEl) tfEl.textContent = sw.T ? _fpmNum(sw.T, 2) + ' s · ' + _fpmNum(1 / sw.T, 2) + ' Hz' : '—';
  const sb = document.getElementById('swgStartBtn'), pb = document.getElementById('swgStopBtn');
  if (sb) sb.disabled = running; if (pb) pb.disabled = !running;
}

// Scheitelwerte
function _swgScheitelAuto() {
  _swg.rows = [];
  _swgPeaks(9).forEach(p => {
    const yhat = p.yhat * (1 + (Math.random() - 0.5) * 0.02);   // kleine Ablesestreuung
    _swg.rows.push({ id: _swg.nextId++, t: Math.round(p.t * 100) / 100, yhat: Math.round(yhat * 100) / 100 });
  });
  _swgRenderTable(); _mlabDrawPlot('swgPlot', _swg);
}
function _swgDelRow(id) { _swg.rows = _swg.rows.filter(r => r.id !== id); _swgRenderTable(); _mlabDrawPlot('swgPlot', _swg); }
function _swgClear() {
  if (_swg.rows.length && !confirm('Alle ' + _swg.rows.length + ' Scheitelwerte löschen?')) return;
  _swg.rows = []; _swgRenderTable(); _mlabDrawPlot('swgPlot', _swg);
}
function _swgRenderTable() {
  const tb = document.getElementById('swgTbody'); if (!tb) return;
  const empty = document.getElementById('swgEmpty');
  if (empty) empty.style.display = _swg.rows.length ? 'none' : 'block';
  tb.innerHTML = _swg.rows.map((r, i) =>
    `<tr><td>${i}</td><td>${_fpmNum(r.t, 2)}</td><td><b>${_fpmNum(r.yhat, 2)}</b></td>
       <td>${_fpmNum(Math.log(r.yhat), 3)}</td>
       <td class="fpm-del" onclick="_swgDelRow(${r.id})" title="löschen">✕</td></tr>`).join('');
}

// Wiring
function _swgSetPreset(i) { _mlabSetPreset(_swg, i); }
function _swgSetFn(s) { _mlabSetFn(_swg, s); }
function _swgTheorieFn() { _mlabTheorieFn(_swg); }
function _swgClearFn() { _mlabClearFn(_swg); }
function _swgSetBool(k, v) { _swg[k] = v; _mlabDrawPlot('swgPlot', _swg); }

// ── Animation + y-t-Diagramm ───────────────────────────
function _swgUpdate(dt) {
  if (!_swg || !_swg.running) return;
  _swg.t += dt;
  if (_swg.sw.state === 'running') _swgSWRender();
}
function _swgDraw(ctx, cv) {
  if (!_swg) return;
  _swgDrawOsz(ctx, cv);
  const g = document.getElementById('swgGraph');
  if (g && g.getContext) _swgDrawGraph(g.getContext('2d'), g);
}
function _swgDrawOsz(ctx, cv) {
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#f0f9ff'; ctx.fillRect(0, 0, W, H);
  const tNow = _swg.t % _SWG_WIN;
  const y = _swgY(tNow);              // aktuelle Elongation in cm
  const cx = W / 2, top = 24, PX = 12;   // 12 px pro cm
  // Ruhelage
  ctx.strokeStyle = '#94a3b8'; ctx.setLineDash([4, 4]); ctx.lineWidth = 1;
  const zeroY = H / 2 + 10;
  if (_swg.osz === 'fad') { ctx.beginPath(); ctx.moveTo(20, top + 8); ctx.lineTo(W - 20, top + 8); ctx.stroke(); }
  ctx.setLineDash([]);
  ctx.fillStyle = '#1e293b'; ctx.font = '700 11px sans-serif'; ctx.textAlign = 'left';
  const oszName = (_SWG_OSZ.find(o => o.k === _swg.osz) || {}).n || '';
  ctx.fillText(oszName, 10, 16);
  ctx.fillStyle = '#7c3aed'; ctx.font = '11px sans-serif';
  ctx.fillText('y = ' + _fpmNum(y, 2) + ' cm', 10, H - 8);

  if (_swg.osz === 'fad' || _swg.osz === 'hem') {
    // Pendel: horizontale Auslenkung
    const L = H - top - 44, ang = (y / _swg.amp0) * 0.5;   // Winkel ~ Auslenkung
    const bx = cx + Math.sin(ang) * L, by = top + 8 + Math.cos(ang) * L;
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 4; ctx.beginPath(); ctx.moveTo(cx - 30, top + 8); ctx.lineTo(cx + 30, top + 8); ctx.stroke();
    ctx.strokeStyle = '#475569'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(cx, top + 8); ctx.lineTo(bx, by); ctx.stroke();
    ctx.fillStyle = _swg.osz === 'hem' ? '#b45309' : '#f97316'; ctx.beginPath(); ctx.arc(bx, by, 13, 0, 2 * Math.PI); ctx.fill();
  } else if (_swg.osz === 'rohr') {
    // U-Rohr: Wasserspiegel links/rechts gegenphasig
    const lx = cx - 55, rx = cx + 55, wBase = H - 30, uw = 26;
    ctx.strokeStyle = '#64748b'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(lx - uw / 2, top + 6); ctx.lineTo(lx - uw / 2, wBase); ctx.arc(cx, wBase, cx - (lx - uw / 2), Math.PI, 0, true);
    ctx.lineTo(rx + uw / 2, top + 6); ctx.stroke();
    ctx.fillStyle = '#38bdf8';
    const lvl = y * PX;
    ctx.fillRect(lx - uw / 2 + 2, (H / 2) - lvl, uw - 3, wBase - ((H / 2) - lvl));
    ctx.fillRect(rx - uw / 2 + 2, (H / 2) + lvl, uw - 3, wBase - ((H / 2) + lvl));
  } else {
    // Federpendel: vertikale Masse
    const massY = zeroY + y * PX;
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 4; ctx.beginPath(); ctx.moveTo(cx - 40, top); ctx.lineTo(cx + 40, top); ctx.stroke();
    ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 2; ctx.beginPath();
    const N = 16, len = massY - top;
    for (let i = 0; i <= N; i++) { const u = i / N; ctx.lineTo(cx + Math.sin(u * N * Math.PI) * 10 * Math.min(1, Math.min(u, 1 - u) * 6), top + u * len); }
    ctx.stroke();
    ctx.fillStyle = '#475569'; ctx.beginPath(); ctx.roundRect ? ctx.roundRect(cx - 22, massY, 44, 24, 4) : ctx.rect(cx - 22, massY, 44, 24); ctx.fill();
  }
}
function _swgDrawGraph(ctx, cv) {
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
  const padL = 34, padB = 22, padT = 10, padR = 10;
  const x0 = padL, y0 = H - padB, x1 = W - padR, y1 = padT;
  const A = _swg.amp0 * 1.1;
  const X = t => x0 + t / _SWG_WIN * (x1 - x0);
  const Y = v => (y0 + y1) / 2 - v / A * ((y0 - y1) / 2);
  // Gitter (Sekunden)
  ctx.strokeStyle = '#eef2f7'; ctx.lineWidth = 1; ctx.font = '9px sans-serif';
  for (let t = 0; t <= _SWG_WIN; t += 1) {
    ctx.beginPath(); ctx.moveTo(X(t), y1); ctx.lineTo(X(t), y0); ctx.stroke();
    if (t % 2 === 0) { ctx.fillStyle = '#94a3b8'; ctx.textAlign = 'center'; ctx.fillText(t, X(t), y0 + 12); }
  }
  // Nulllinie (Ruhelage)
  ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 1.2; ctx.beginPath(); ctx.moveTo(x0, Y(0)); ctx.lineTo(x1, Y(0)); ctx.stroke();
  ctx.fillStyle = '#94a3b8'; ctx.textAlign = 'right'; ctx.fillText('0', x0 - 3, Y(0) + 3);
  ctx.fillText('+ŷ', x0 - 3, Y(_swg.amp0) + 3); ctx.fillText('−ŷ', x0 - 3, Y(-_swg.amp0) + 3);
  ctx.fillStyle = '#475569'; ctx.font = '700 9px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText('y in cm', x0, y1 + 8); ctx.textAlign = 'right'; ctx.fillText('t in s', x1, y0 + 12);
  // Einhuellende bei Daempfung
  if (_swgDelta() > 0) {
    ctx.strokeStyle = '#16a34a'; ctx.lineWidth = 1; ctx.setLineDash([3, 3]);
    [1, -1].forEach(s => { ctx.beginPath(); for (let t = 0; t <= _SWG_WIN; t += 0.1) { const yy = Y(s * _swgYmax(t)); t === 0 ? ctx.moveTo(X(t), yy) : ctx.lineTo(X(t), yy); } ctx.stroke(); });
    ctx.setLineDash([]);
  }
  // y-t-Kurve
  ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 1.8; ctx.beginPath();
  for (let t = 0; t <= _SWG_WIN; t += 0.03) { const yy = Y(_swgY(t)); t === 0 ? ctx.moveTo(X(t), yy) : ctx.lineTo(X(t), yy); }
  ctx.stroke();
  // Ablese-Cursor
  const ct = _swg.cursor;
  ctx.strokeStyle = '#db2777'; ctx.lineWidth = 1; ctx.setLineDash([4, 3]);
  ctx.beginPath(); ctx.moveTo(X(ct), y1); ctx.lineTo(X(ct), y0); ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle = '#db2777'; ctx.beginPath(); ctx.arc(X(ct), Y(_swgY(ct)), 4, 0, 2 * Math.PI); ctx.fill();
  // "Jetzt"-Punkt
  const tn = _swg.t % _SWG_WIN;
  ctx.fillStyle = '#f97316'; ctx.beginPath(); ctx.arc(X(tn), Y(_swgY(tn)), 3.5, 0, 2 * Math.PI); ctx.fill();
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT (10-teilige Struktur) – Felder lokal gespeichert
// ═══════════════════════════════════════════════════════
function _swgArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('schwingung')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('schwingung')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Titel</div><div class="ab-t"><b>Merkmale von Schwingungen</b> – Periodendauer, Frequenz, Amplitude und Dämpfung</div></div>

      <div class="ab-sec"><div class="ab-h">2 · Kurze Beschreibung</div>
        <div class="ab-t">Ein schwingungsfähiges System (ein <b>Oszillator</b>) bewegt sich immer wieder hin und her – zum Beispiel ein Federpendel, ein Fadenpendel oder eine Wassersäule im U-Rohr. Die Simulation zeichnet die Bewegung als <b>y-t-Diagramm</b> auf. Du kannst Werte ablesen und messen.</div></div>

      <div class="ab-sec"><div class="ab-h">3 · Ziel / Fragestellung</div>
        <div class="ab-t">Wie beschreibt man eine Schwingung mit Zahlen? Und was ändert sich, wenn eine Schwingung <b>gedämpft</b> ist?</div></div>

      <div class="ab-sec"><div class="ab-h">4 · Benötigte Einstellungen</div>
        <div class="ab-t">In der Simulation oben: <b>Oszillator</b>, Regler <b>Amplitude ŷ₀</b> und <b>Periodendauer T</b>, die Schalter <b>ungedämpft / schwach / stark gedämpft</b>, die <b>Stoppuhr</b> und der rosa <b>Ablese-Cursor</b>.</div></div>

      <div class="ab-sec"><div class="ab-h">5 · Schritt-für-Schritt-Anleitung</div>
        <ol class="ab-ol">
          <li>Wähle den Oszillator <b>Federpendel</b> und stelle <b>ungedämpft</b> ein.</li>
          <li>Starte die <b>Stoppuhr</b>, lass genau <b>n = 5</b> Perioden zählen, drücke <b>Stopp</b>. Notiere Δt, T und f.</li>
          <li>Lies mit dem <b>Ablese-Cursor</b> die Elongation y zu drei Zeitpunkten ab.</li>
          <li>Schalte auf <b>schwach gedämpft</b> und drücke <b>„Scheitelwerte aufnehmen"</b>.</li>
          <li>Öffne unten die Auswertung, schalte auf <b>t → ln(ŷ)</b> und lege die <b>Ausgleichsgerade</b> an.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">6 · Vermutung (vor der Messung)</div>
        <div class="ab-t">Was passiert mit der Amplitude, wenn eine Schwingung gedämpft ist? Und ändert sich dabei die Periodendauer T? Schreibe deine Vermutung auf:</div>
        ${ta('v1', 'Meine Vermutung: …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">7 · Beobachtungen & Messwerte</div>
        <table class="ab-table"><tbody>
          <tr><td>Perioden n</td><td>${inp('m_n', 'n')}</td><td>Zeit Δt (s)</td><td>${inp('m_dt', 's')}</td></tr>
          <tr><td>T = Δt/n (s)</td><td>${inp('m_T', 's')}</td><td>f = 1/T (Hz)</td><td>${inp('m_f', 'Hz')}</td></tr>
          <tr><td>y bei t₁ = ____ s</td><td>${inp('m_y1', 'cm')}</td><td>y bei t₂ = ____ s</td><td>${inp('m_y2', 'cm')}</td></tr>
        </tbody></table>
        <div class="ab-t" style="margin-top:6px">Trage 3 Scheitelwerte aus der Tabelle ab:</div>
        <table class="ab-table"><tbody>
          <tr><td>ŷ₀ (cm)</td><td>${inp('s_y0', 'cm')}</td><td>ŷ nach 1 Periode</td><td>${inp('s_y1', 'cm')}</td><td>ŷ nach 3 Perioden</td><td>${inp('s_y3', 'cm')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">8 · Auswertung</div>
        <div class="ab-t">Welche Auftragung ergibt eine <b>Gerade</b>? Was bedeutet ihre Steigung? Wie groß sind Dämpfung δ und Halbwertszeit t½?</div>
        ${ta('a1', 'δ = … ,  t½ = … ,  Begründung: …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">9 · Erklärung in eigenen Worten</div>
        <div class="ab-t">Erkläre mit eigenen Worten, was „gedämpft" bedeutet und warum die Periodendauer dabei (fast) gleich bleibt.</div>
        ${ta('e1', 'Meine Erklärung: …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">10 · Transfer / Vertiefung</div>
        <div class="ab-t">Wähle das <b>Hemmungspendel</b> und beobachte die Kurve genau. Die Schwingung ist leicht <b>unsymmetrisch</b> (die Ausschläge nach oben und unten sind unterschiedlich groß). Stelle eine <b>Vermutung</b> auf, woran das liegen könnte.</div>
        ${ta('t1', 'Meine Vermutung zum Hemmungspendel: …', 3)}</div>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('schwingung')">🗑 Arbeitsblatt zurücksetzen</button>
      </div>`;
  return _abWrap('schwingung', 'Merkmale von Schwingungen', body);
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT-GATE (wiederverwendbar) – Passwortschutz 0123
// Einheitlich fuer alle Sims: das Arbeitsblatt ist erst nach Eingabe
// des Passworts sichtbar. Einmal pro Sitzung freigeschaltet.
// ═══════════════════════════════════════════════════════
const _AB_PW = '0123';
let _abUnlocked = false;
function _abWrap(ns, titel, bodyHtml) {
  const open = _abUnlocked;
  return `<div class="ab-wrap">
    <div class="ab-summary">📝 Arbeitsblatt – ${titel}
      <span class="ab-hint" id="abHint_${ns}">${open ? '(freigeschaltet · Eingaben werden im Browser gespeichert)' : '🔒 durch Passwort geschützt'}</span></div>
    <div class="ab-gate" id="abGate_${ns}" style="display:${open ? 'none' : 'flex'}">
      <span class="ab-gate-t">🔒 Dieses Arbeitsblatt ist passwortgeschützt. Bitte das Passwort eingeben:</span>
      <div class="ab-gate-row">
        <input type="password" class="ab-pw" id="abPw_${ns}" placeholder="Passwort" autocomplete="off"
          onkeydown="if(event.key==='Enter')_abUnlock('${ns}')">
        <button class="sim-btn primary" onclick="_abUnlock('${ns}')">🔓 Öffnen</button>
        <span class="ab-pw-err" id="abPwErr_${ns}"></span>
      </div>
    </div>
    <div class="ab-body" id="abBody_${ns}" style="display:${open ? 'block' : 'none'}">${bodyHtml}</div>
  </div>`;
}
function _abUnlock(ns) {
  const inp = document.getElementById('abPw_' + ns);
  const err = document.getElementById('abPwErr_' + ns);
  if (inp && String(inp.value).trim() === _AB_PW) {
    _abUnlocked = true;
    const g = document.getElementById('abGate_' + ns); if (g) g.style.display = 'none';
    const b = document.getElementById('abBody_' + ns); if (b) b.style.display = 'block';
    const h = document.getElementById('abHint_' + ns); if (h) h.textContent = '(freigeschaltet · Eingaben werden im Browser gespeichert)';
    _abRestore(ns);
  } else {
    if (err) err.textContent = 'Falsches Passwort.';
    if (inp) { inp.value = ''; }
  }
}

// ── Arbeitsblatt-Persistenz (wiederverwendbar) ─────────
function _abSave(ns) {
  try {
    if (typeof localStorage === 'undefined') return;
    const data = {};
    document.querySelectorAll('[data-abk]').forEach(el => { data[el.getAttribute('data-abk')] = el.value; });
    localStorage.setItem('ls_ab_' + ns, JSON.stringify(data));
  } catch (e) { }
}
function _abRestore(ns) {
  try {
    if (typeof localStorage === 'undefined') return;
    const raw = localStorage.getItem('ls_ab_' + ns); if (!raw) return;
    const data = JSON.parse(raw);
    document.querySelectorAll('[data-abk]').forEach(el => { const k = el.getAttribute('data-abk'); if (k in data) el.value = data[k]; });
  } catch (e) { }
}
function _abClear(ns) {
  if (!confirm('Alle Eingaben im Arbeitsblatt löschen?')) return;
  try { if (typeof localStorage !== 'undefined') localStorage.removeItem('ls_ab_' + ns); } catch (e) { }
  document.querySelectorAll('[data-abk]').forEach(el => { el.value = ''; });
}

