function _mffArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('magfeld')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('magfeld')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Wie sieht der unsichtbare Bereich um einen Magneten aus – und wo ist er am stärksten?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, das Magnetfeld sieht so aus … Am stärksten ist es …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Bewege den <b>Prüfkompass</b> mit den Reglern rund um den Magneten.</li>
          <li>Beobachte: In welche Richtung zeigt die rote Nadelspitze an verschiedenen Stellen?</li>
          <li>Blende die <b>Feldlinien</b> und das <b>Kompass-Raster</b> ein.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtung</div>
        <ol class="ab-ol">
          <li>Wo beginnen die Feldlinien, wo enden sie? ${inp('b1', 'von … nach …')}</li>
          <li>Wo stehen die Linien besonders dicht? ${inp('b2', 'nah an …')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne den Magneten (N und S) und die Feldlinien mit Pfeilen ein.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Richtet sich die Kompassnadel immer entlang der Feldlinien aus? ${inp('a1', 'ja/nein')}</li>
          <li>Wo ist das Magnetfeld am stärksten – nah an den Polen oder weit weg? ${inp('a2', '')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Der Bereich um einen Magneten heißt <b>Magnetfeld</b>. Man stellt es mit <b>Feldlinien</b> dar.<br>
        Außerhalb des Magneten zeigen die Feldlinien vom ${inp('m1', 'welcher Pol?')} zum ${inp('m2', 'welcher Pol?')}.<br>
        Wo die Linien ${inp('m3', 'dicht/locker')} sind, ist das Feld am stärksten.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Streut man Eisenfeilspäne auf ein Blatt Papier über einem Magneten, ordnen sie sich zu Linien. Erkläre, warum. Was haben die Eisenspäne mit den kleinen Kompassnadeln gemeinsam?</div>
        ${ta('tr1', 'Die Eisenspäne …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="mffMini">${_mffMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_mffSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_mffSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_mffSelf(3)">😃 sicher</button>
          <span id="mffSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="mffSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Die Kompassnadeln richten sich tangential zu den Feldlinien aus. Außerhalb verlaufen die Linien vom Nord- zum Südpol, gebündelt und dicht nahe den Polen (dort stärkstes Feld), weiter außen locker (schwächer).</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Feldlinien sind ein Modell: Richtung = Richtung, in die ein Kompass-Nordpol zeigt (außen N→S). Liniendichte ~ Feldstärke. Linien schneiden sich nie.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Feldlinien sind echte Fäden." (2) „Das Feld ist überall gleich stark." (3) „Nur am Nordpol gibt es ein Feld."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Prüfkompass langsam bewegen lassen; Raster + Linien nacheinander einblenden; Bezug zu Eisenfeilspänen herstellen.</div>
        <div class="ab-t"><b>Musterlösung.</b> 4.1 „von N nach S" · 4.2 „nah an den Polen" · 6.1 „ja" · 6.2 „nah an den Polen". Merksatz: Nordpol · Südpol · dicht. Transfer: Eisenspäne werden selbst zu kleinen Magneten und richten sich wie Kompassnadeln entlang der Feldlinien aus. Minidiagnose: 1→„Feldlinien" · 2→„von Nord zu Süd" · 3→„nah an den Polen".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('magfeld')">🗑 Arbeitsblatt zurücksetzen</button>
      </div>`;
  return _abWrap('magfeld', 'Wie sieht ein Magnetfeld aus?', body);
}

const _MFF_MINI = [
  { q: '1. Wie stellt man ein Magnetfeld sichtbar dar?',
    opts: ['Mit Feldlinien', 'Mit Zahlen', 'Mit Farben allein'], correct: 0,
    fb: ['Richtig! Feldlinien zeigen Richtung und Stärke des Feldes.',
         'Zahlen allein zeigen die Form des Feldes nicht.',
         'Man braucht Linien, die die Richtung zeigen.'] },
  { q: '2. In welche Richtung verlaufen die Feldlinien außerhalb des Magneten?',
    opts: ['Von Süd zu Nord', 'Von Nord zu Süd', 'Im Kreis um die Mitte'], correct: 1,
    fb: ['Andersherum: außen von Nord nach Süd.',
         'Richtig! Außerhalb zeigen die Linien vom Nordpol zum Südpol.',
         'Beim Stabmagneten laufen sie von Pol zu Pol, nicht im Kreis.'] },
  { q: '3. Wo ist das Magnetfeld am stärksten?',
    opts: ['Weit weg vom Magneten', 'Nah an den Polen', 'Überall gleich'], correct: 1,
    fb: ['Weit weg wird das Feld schwächer.',
         'Richtig! Nah an den Polen sind die Linien dicht – dort ist das Feld am stärksten.',
         'Das Feld ist nicht überall gleich stark.'] }
];
function _mffMiniHTML() {
  return _MFF_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_mffAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="mffFb${qi}"></div></div>`).join('');
}
function _mffAns(qi, oi) {
  const m = _MFF_MINI[qi], el = document.getElementById('mffFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _mffSelf(n) {
  const out = document.getElementById('mffSelfOut'), val = document.getElementById('mffSelfVal');
  if (val) { val.value = String(n); _abSave('magfeld'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.1.4  WIE FUNKTIONIERT EIN KOMPASS?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Strom und Magnetismus"
// Handlungsorientiert: Kompassnadel im Erdmagnetfeld. Der Schüler
// stößt die Nadel an (sie pendelt zurück nach Norden), bringt einen
// Magneten heran (Nadel dreht sich zum Magneten) und schaltet das
// Erdmagnetfeld aus. Nadel richtet sich immer nach dem Gesamtfeld.
// (nutzt _magFieldAt aus dem Magnetfeld-Modul nicht – eigenes,
//  schülergerechtes Vektor-Summenmodell.)
// ═══════════════════════════════════════════════════════

const _KOM_EARTH = 1;      // Stärke des Erdfeldes (Richtung Norden)
const _KOM_MAG = 30;       // Magnetstärke: Einfluss = _KOM_MAG / d²
const _KOM_SPRING = 34, _KOM_DAMP = 4.2;
let _kom = null;

function _komInit() {
  _kom = { ang: -Math.PI / 2, vel: 0, earthOn: true, magnetOn: false, phi: 120, dist: 6 };
}

// Zielrichtung der Nadel = Richtung des Gesamtfeldes
function _komTarget() {
  let vx = 0, vy = 0;
  if (_kom.earthOn) vy += -_KOM_EARTH;                 // Norden = oben
  if (_kom.magnetOn) {
    const s = _KOM_MAG / (_kom.dist * _kom.dist);
    const a = _kom.phi * Math.PI / 180;
    vx += Math.cos(a) * s; vy += Math.sin(a) * s;
  }
  if (vx === 0 && vy === 0) return _kom.ang;           // kein Feld: Nadel bleibt
  return Math.atan2(vy, vx);
}

function _komHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim kom-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🧭 Wie funktioniert ein Kompass?</h3>
    <div class="fpm-note" style="margin-top:2px">Die Kompassnadel ist ein kleiner drehbarer Magnet. Stoße sie an und beobachte, wie sie zurück nach Norden pendelt. Bringe dann einen Magneten heran.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="komAnim" width="440" height="280" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" onclick="_komStoss()">👆 Nadel anstoßen</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Einstellungen</div>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" id="komEarth" onclick="_komToggle('earthOn')">🌍 Erdmagnetfeld</button>
          <button class="sim-btn" id="komMag" onclick="_komToggle('magnetOn')">🧲 Magnet in der Nähe</button>
        </div>
        <div class="phys-ctrl" style="margin-top:10px">
          <span class="phys-ctrl-label">Magnet – Richtung: <b id="komPhiLbl">120°</b></span>
          <input type="range" id="komPhi" min="0" max="360" step="10" value="120"
            oninput="_komSetPhi(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="phys-ctrl" style="margin-top:8px">
          <span class="phys-ctrl-label">Magnet – Abstand: <b id="komDLbl">6 cm</b></span>
          <input type="range" id="komDist" min="3" max="15" step="1" value="6"
            oninput="_komSetDist(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="fpm-note" style="margin-top:10px">Ohne Magnet zeigt die rote Nadelspitze immer nach <b>Norden</b>. Ein Magnet in der Nähe ist stärker als das Erdfeld – die Nadel dreht sich zu ihm.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Die Erde ist selbst ein großer Magnet. &nbsp;|&nbsp; Deshalb richtet sich die Nadel nach Norden – solange kein anderer Magnet stört.
    </p>
    ${_komArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _komStoss() { if (_kom) _kom.vel += 9; }
function _komSetPhi(v) { _kom.phi = +v; const e = document.getElementById('komPhiLbl'); if (e) e.textContent = _fpmNum(+v, 0) + '°'; }
function _komSetDist(v) { _kom.dist = +v; const e = document.getElementById('komDLbl'); if (e) e.textContent = _fpmNum(+v, 0) + ' cm'; }
function _komToggle(k) {
  _kom[k] = !_kom[k];
  document.getElementById(k === 'earthOn' ? 'komEarth' : 'komMag')?.classList.toggle('primary', _kom[k]);
}

// ── Animation (gedämpfte Ausrichtung) ──────────────────
function _komUpdate(dt) {
  if (!_kom) return;
  const t = _komTarget();
  let d = t - _kom.ang; while (d > Math.PI) d -= 2 * Math.PI; while (d < -Math.PI) d += 2 * Math.PI;
  const acc = _KOM_SPRING * Math.sin(d) - _KOM_DAMP * _kom.vel;
  _kom.vel += acc * dt; _kom.ang += _kom.vel * dt;
}
function _komDraw(ctx, cv) {
  if (!_kom) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, W, H);
  const cx = 150, cy = H / 2, R = 78;
  // Erdfeld-Pfeil nach Norden
  if (_kom.earthOn) {
    ctx.strokeStyle = '#bfdbfe'; ctx.lineWidth = 2; ctx.setLineDash([5, 4]);
    for (let x = 40; x < W - 20; x += 40) { ctx.beginPath(); ctx.moveTo(x, H - 20); ctx.lineTo(x, 20); ctx.stroke(); }
    ctx.setLineDash([]);
    ctx.fillStyle = '#60a5fa'; ctx.font = '700 10px sans-serif'; ctx.textAlign = 'left';
    ctx.fillText('Erdmagnetfeld → Norden', 40, 14);
  }
  // Kompassdose
  ctx.fillStyle = '#fff'; ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.arc(cx, cy, R, 0, 2 * Math.PI); ctx.fill(); ctx.stroke();
  ctx.fillStyle = '#64748b'; ctx.font = '700 13px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('N', cx, cy - R + 12); ctx.fillText('S', cx, cy + R - 12);
  ctx.fillText('W', cx - R + 12, cy); ctx.fillText('O', cx + R - 12, cy);
  ctx.textBaseline = 'alphabetic';
  // Nadel
  const len = R - 20, dx = Math.cos(_kom.ang) * len, dy = Math.sin(_kom.ang) * len;
  ctx.lineWidth = 6; ctx.lineCap = 'round';
  ctx.strokeStyle = '#dc2626'; ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + dx, cy + dy); ctx.stroke();
  ctx.strokeStyle = '#2563eb'; ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx - dx, cy - dy); ctx.stroke();
  ctx.fillStyle = '#1e293b'; ctx.beginPath(); ctx.arc(cx, cy, 5, 0, 2 * Math.PI); ctx.fill();
  // Magnet
  if (_kom.magnetOn) {
    const a = _kom.phi * Math.PI / 180;
    const mxc = cx + Math.cos(a) * (R + 8 + _kom.dist * 5), myc = cy + Math.sin(a) * (R + 8 + _kom.dist * 5);
    const mw = 44, mh = 18;
    ctx.save(); ctx.translate(mxc, myc); ctx.rotate(a);
    ctx.fillStyle = '#2563eb'; ctx.fillRect(-mw / 2, -mh / 2, mw / 2, mh);
    ctx.fillStyle = '#dc2626'; ctx.fillRect(0, -mh / 2, mw / 2, mh);
    ctx.fillStyle = '#fff'; ctx.font = '700 11px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText('S', -mw / 4, 0); ctx.fillText('N', mw / 4, 0);
    ctx.restore(); ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = '#7c3aed'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('Magnet', mxc, myc + 26);
  }
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.1.4  (ns = 'kompass') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _komArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('kompass')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('kompass')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Warum zeigt eine Kompassnadel immer nach Norden – und was bringt sie aus dem Takt?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, die Nadel zeigt nach Norden, weil … Aus dem Takt bringt sie …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Drücke <b>„Nadel anstoßen"</b>. Beobachte, wohin die Nadel nach dem Pendeln zeigt.</li>
          <li>Schalte das <b>Erdmagnetfeld</b> aus und wieder ein. Was ändert sich?</li>
          <li>Schalte <b>„Magnet in der Nähe"</b> ein und verändere Richtung und Abstand.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtung</div>
        <ol class="ab-ol">
          <li>Wohin zeigt die rote Spitze ohne Magnet? ${inp('b1', 'nach …')}</li>
          <li>Was macht die Nadel, wenn ein Magnet nah ist? ${inp('b2', '')}</li>
          <li>Wirkt der Magnet stärker bei kleinem oder großem Abstand? ${inp('b3', '')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne den Kompass mit der Nadel, die nach Norden zeigt. Zeichne dann einen Magneten daneben und wohin sich die Nadel dreht.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Warum zeigt die Nadel ohne Störung nach Norden? ${inp('a1', 'weil die Erde …')}</li>
          <li>Warum sollte man einen Kompass nicht neben Eisen oder Magnete legen? ${inp('a2', '')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Die Kompassnadel ist ein kleiner drehbarer ${inp('m1', 'was?')}.<br>
        Sie richtet sich nach dem ${inp('m2', 'welches Feld?')} der Erde aus und zeigt nach Norden.<br>
        Ein Magnet in der Nähe ist ${inp('m3', 'stärker/schwächer')} und lenkt die Nadel ab.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Du wanderst und legst deinen Kompass aus Versehen auf die Motorhaube eines Autos (viel Eisen). Warum kann er jetzt falsch anzeigen? Was tust du besser?</div>
        ${ta('tr1', 'Der Kompass zeigt falsch, weil … Besser ist …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="komMini">${_komMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_komSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_komSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_komSelf(3)">😃 sicher</button>
          <span id="komSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="komSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Nach dem Anstoßen pendelt die Nadel und richtet sich wieder nach Norden. Erdfeld aus → Nadel bleibt beliebig stehen (kein Richtungsfeld). Magnet nah → Nadel dreht sich zum Magneten; Wirkung nimmt mit kleinerem Abstand stark zu.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Die Nadel ist ein Dauermagnet und richtet sich entlang des Gesamtfeldes aus. Das Erdmagnetfeld wirkt wie ein großer Stabmagnet (magnetischer Südpol nahe dem geografischen Nordpol). Ein nahes Magnetfeld/Eisen überlagert das schwache Erdfeld.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Der Nordstern zieht die Nadel an." (2) „Die Nadel zeigt immer exakt geografisch Nord" (Deklination – hier nicht vertiefen). (3) „Ein Kompass funktioniert überall gleich, egal was daneben liegt."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Erdfeldpfeile einblenden; erst ohne Magnet anstoßen lassen; dann Magnet nur langsam nähern; Bezug zu Eisen (Auto, Werkzeug).</div>
        <div class="ab-t"><b>Musterlösung.</b> 4.1 „Norden" · 4.2 „dreht sich zum Magneten" · 4.3 „kleiner Abstand". 6.1 „weil die Erde ein Magnet ist" · 6.2 „Eisen/Magnete lenken die Nadel ab". Merksatz: Magnet · Magnetfeld · stärker. Transfer: Das Eisen der Motorhaube lenkt die Nadel ab → weg vom Auto, in die Hand nehmen. Minidiagnose: 1→„weil die Erde ein Magnet ist" · 2→„dreht sich zum Magneten" · 3→„ein Magnet/Eisen in der Nähe".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('kompass')">🗑 Arbeitsblatt zurücksetzen</button>
      </div>`;
  return _abWrap('kompass', 'Wie funktioniert ein Kompass?', body);
}

const _KOM_MINI = [
  { q: '1. Warum zeigt eine Kompassnadel nach Norden?',
    opts: ['Weil Norden kälter ist', 'Weil die Erde selbst ein Magnet ist', 'Weil die Sonne dort steht'], correct: 1,
    fb: ['Mit der Temperatur hat es nichts zu tun.',
         'Richtig! Das Erdmagnetfeld richtet die Nadel nach Norden aus.',
         'Die Sonne bewegt sich – der Kompass zeigt trotzdem konstant nach Norden.'] },
  { q: '2. Was macht die Nadel, wenn ein starker Magnet direkt daneben liegt?',
    opts: ['Sie zeigt weiter genau nach Norden', 'Sie dreht sich zum Magneten', 'Sie bleibt stehen'], correct: 1,
    fb: ['Der nahe Magnet ist stärker als das Erdfeld.',
         'Richtig! Der nahe Magnet ist stärker und lenkt die Nadel ab.',
         'Sie bewegt sich – hin zum Magneten.'] },
  { q: '3. Wann zeigt ein Kompass falsch?',
    opts: ['Wenn es regnet', 'Wenn Eisen oder ein Magnet in der Nähe ist', 'Wenn es dunkel ist'], correct: 1,
    fb: ['Regen stört den Kompass nicht.',
         'Richtig! Eisen oder Magnete in der Nähe lenken die Nadel ab.',
         'Dunkelheit hat keinen Einfluss.'] }
];
function _komMiniHTML() {
  return _KOM_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_komAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="komFb${qi}"></div></div>`).join('');
}
function _komAns(qi, oi) {
  const m = _KOM_MINI[qi], el = document.getElementById('komFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _komSelf(n) {
  const out = document.getElementById('komSelfOut'), val = document.getElementById('komSelfVal');
  if (val) { val.value = String(n); _abSave('kompass'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.2.1  WANN LEUCHTET EINE LAMPE?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Strom und Magnetismus"
// Handlungsorientiert: einfacher Stromkreis (Batterie, Kabel,
// Schalter, Lampe). Schalter öffnen/schließen und ein Kabel
// unterbrechen. Die Lampe leuchtet nur, wenn der Stromkreis
// vollständig geschlossen ist. Nur ungefährliche Kleinspannung.
// ═══════════════════════════════════════════════════════

let _lmp = null;
function _lmpInit() { _lmp = { closed: true, wireOk: true, t: 0 }; }
function _lmpOn() { return _lmp.closed && _lmp.wireOk; }

function _lmpHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim lmp-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">💡 Wann leuchtet eine Lampe?</h3>
    <div class="fpm-note" style="margin-top:2px">Ein Stromkreis aus Batterie, Kabeln, Schalter und Lampe. Probiere aus: Wann leuchtet die Lampe – und wann nicht? (Nur ungefährliche Batterie-Kleinspannung.)</div>
    <div class="fpm-grid">
      <div>
        <canvas id="lmpAnim" width="440" height="260" class="phys-anim-cv"></canvas>
      </div>
      <div>
        <div class="fpm-label">Probiere aus</div>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" id="lmpSw" onclick="_lmpToggle('closed')">🔘 Schalter: <span id="lmpSwT">geschlossen</span></button>
        </div>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" id="lmpWi" onclick="_lmpToggle('wireOk')">🔌 Kabel: <span id="lmpWiT">heil</span></button>
        </div>
        <div class="lmp-status" id="lmpStatus"></div>
        <div class="fpm-tablewrap" style="margin-top:10px">
          <table class="sim-table">
            <thead><tr><th>Schalter</th><th>Kabel</th><th>Lampe</th></tr></thead>
            <tbody>
              <tr><td>geschlossen</td><td>heil</td><td><b class="msf-ja">leuchtet</b></td></tr>
              <tr><td>offen</td><td>heil</td><td><b class="msf-nein">aus</b></td></tr>
              <tr><td>geschlossen</td><td>unterbrochen</td><td><b class="msf-nein">aus</b></td></tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Die Lampe leuchtet nur im <b>geschlossenen Stromkreis</b>. &nbsp;|&nbsp; Schon eine einzige Unterbrechung stoppt den Strom.
    </p>
    ${_lmpArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _lmpToggle(k) {
  _lmp[k] = !_lmp[k];
  const on = _lmp.closed, wi = _lmp.wireOk;
  const swT = document.getElementById('lmpSwT'); if (swT) swT.textContent = on ? 'geschlossen' : 'offen';
  const wiT = document.getElementById('lmpWiT'); if (wiT) wiT.textContent = wi ? 'heil' : 'unterbrochen';
  document.getElementById('lmpSw')?.classList.toggle('primary', on);
  document.getElementById('lmpWi')?.classList.toggle('primary', wi);
  _lmpStatus();
}
function _lmpStatus() {
  const el = document.getElementById('lmpStatus'); if (!el) return;
  if (_lmpOn()) { el.textContent = '✓ Stromkreis geschlossen → die Lampe leuchtet!'; el.className = 'lmp-status on'; }
  else if (!_lmp.closed) { el.textContent = '✗ Schalter offen → kein Strom → Lampe aus.'; el.className = 'lmp-status off'; }
  else { el.textContent = '✗ Kabel unterbrochen → kein Strom → Lampe aus.'; el.className = 'lmp-status off'; }
}

// ── Animation ──────────────────────────────────────────
function _lmpUpdate(dt) { if (_lmp) _lmp.t += dt; }
function _lmpDraw(ctx, cv) {
  if (!_lmp) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, W, H);
  const L = 70, R = W - 70, T = 55, B = H - 55, on = _lmpOn();
  // Leitung (Rechteck)
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 4;
  ctx.strokeRect(L, T, R - L, B - T);
  // Stromfluss (animierte Striche) nur wenn geschlossen
  if (on) {
    ctx.strokeStyle = '#22c55e'; ctx.lineWidth = 3;
    ctx.setLineDash([9, 9]); ctx.lineDashOffset = -(_lmp.t * 70) % 18;
    ctx.strokeRect(L, T, R - L, B - T);
    ctx.setLineDash([]); ctx.lineDashOffset = 0;
  }
  const cx = (L + R) / 2, cy = (T + B) / 2;
  // Batterie (unten)
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(cx - 30, B - 12, 60, 24);
  ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(cx - 8, B - 14); ctx.lineTo(cx - 8, B + 14); ctx.stroke();  // langer Strich +
  ctx.lineWidth = 6;
  ctx.beginPath(); ctx.moveTo(cx + 8, B - 8); ctx.lineTo(cx + 8, B + 8); ctx.stroke();     // kurzer Strich −
  ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('Batterie', cx, B + 26);
  // Schalter (rechts)
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(R - 10, cy - 22, 20, 44);
  ctx.fillStyle = '#334155';
  ctx.beginPath(); ctx.arc(R, cy + 18, 3, 0, 2 * Math.PI); ctx.arc(R, cy - 18, 3, 0, 2 * Math.PI); ctx.fill();
  ctx.strokeStyle = _lmp.closed ? '#16a34a' : '#dc2626'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(R, cy + 18);
  if (_lmp.closed) ctx.lineTo(R, cy - 18); else ctx.lineTo(R + 16, cy - 12);
  ctx.stroke();
  ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText('Schalter', R + 6, cy + 30);
  // Kabel-Unterbrechung (links)
  if (!_lmp.wireOk) {
    ctx.fillStyle = '#f8fafc'; ctx.fillRect(L - 4, cy - 14, 8, 28);
    ctx.fillStyle = '#dc2626';
    ctx.beginPath(); ctx.arc(L, cy - 12, 3, 0, 2 * Math.PI); ctx.arc(L, cy + 12, 3, 0, 2 * Math.PI); ctx.fill();
    ctx.font = '9px sans-serif'; ctx.textAlign = 'right'; ctx.fillText('Bruch', L - 6, cy);
  }
  // Lampe (oben)
  const lr = 16;
  if (on) {
    ctx.fillStyle = 'rgba(250,204,21,0.35)';
    ctx.beginPath(); ctx.arc(cx, T, lr + 12, 0, 2 * Math.PI); ctx.fill();
  }
  ctx.fillStyle = on ? '#fde047' : '#e2e8f0';
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(cx, T, lr, 0, 2 * Math.PI); ctx.fill(); ctx.stroke();
  ctx.strokeStyle = on ? '#b45309' : '#94a3b8'; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(cx - 8, T - 8); ctx.lineTo(cx + 8, T + 8); ctx.moveTo(cx + 8, T - 8); ctx.lineTo(cx - 8, T + 8); ctx.stroke();
  ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('Lampe', cx, T - lr - 16);
  // Statuszeile
  ctx.fillStyle = on ? '#16a34a' : '#b45309'; ctx.font = '700 13px sans-serif';
  ctx.fillText(on ? 'Lampe leuchtet 💡' : 'Lampe aus', cx, cy + 5);
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.2.1  (ns = 'lampe') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _lmpArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('lampe')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('lampe')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Wann leuchtet eine Lampe im Stromkreis – und wann bleibt sie dunkel?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, die Lampe leuchtet, wenn …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Öffne und schließe den <b>Schalter</b>. Was macht die Lampe?</li>
          <li>Schließe den Schalter und <b>unterbrich</b> dann das Kabel. Was passiert?</li>
          <li>Trage deine Beobachtungen in die Tabelle ein.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Schalter geschlossen, Kabel heil</td><td>${inp('t1', 'leuchtet/aus')}</td></tr>
          <tr><td>Schalter offen, Kabel heil</td><td>${inp('t2', 'leuchtet/aus')}</td></tr>
          <tr><td>Schalter geschlossen, Kabel unterbrochen</td><td>${inp('t3', 'leuchtet/aus')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne den Stromkreis mit Batterie, Kabel, Schalter und Lampe.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Was muss erfüllt sein, damit die Lampe leuchtet? ${inp('a1', 'der Stromkreis muss …')}</li>
          <li>Reicht eine einzige Unterbrechung, damit die Lampe ausgeht? ${inp('a2', 'ja/nein')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Ein Stromkreis braucht eine ${inp('m1', 'Energie…?')}, ${inp('m2', 'was zum Verbinden?')} und einen Verbraucher (die Lampe).<br>
        Strom fließt nur, wenn der Stromkreis ${inp('m3', 'offen/geschlossen')} ist.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Wenn du zu Hause das Licht mit dem Lichtschalter ausmachst – was passiert dabei mit dem Stromkreis?</div>
        ${ta('tr1', 'Der Lichtschalter …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="lmpMini">${_lmpMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_lmpSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_lmpSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_lmpSelf(3)">😃 sicher</button>
          <span id="lmpSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="lmpSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Nur „Schalter geschlossen + Kabel heil" → Lampe leuchtet. Jede Unterbrechung (offener Schalter ODER Kabelbruch) → Lampe aus.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Strom fließt nur im geschlossenen Stromkreis: Energiequelle (Batterie) + Leiter (Kabel) + Verbraucher (Lampe), alles leitend verbunden. Ein Schalter unterbricht/schließt den Kreis gezielt.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Ein Kabel genügt" (Ein-Draht-Vorstellung). (2) „Strom wird in der Lampe verbraucht und kommt nicht zurück." (3) „Der Schalter erzeugt den Strom."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Kreis mit dem Finger „ablaufen" lassen; betonen: der Kreis muss ganz herum geschlossen sein; nur Kleinspannung (max. 9 V), nie Steckdose.</div>
        <div class="ab-t"><b>Musterlösung.</b> Tabelle: leuchtet / aus / aus. 6.1 „ganz geschlossen sein" · 6.2 „ja". Merksatz: Energiequelle/Batterie · Kabel/Leiter · geschlossen. Transfer: Der Schalter unterbricht den Stromkreis → Lampe aus. Minidiagnose: 1→„im geschlossenen Kreis" · 2→„aus" · 3→„Quelle, Leiter, Verbraucher".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('lampe')">🗑 Arbeitsblatt zurücksetzen</button>
      </div>`;
  return _abWrap('lampe', 'Wann leuchtet eine Lampe?', body);
}

const _LMP_MINI = [
  { q: '1. Wann fließt Strom durch die Lampe?',
    opts: ['Immer', 'Nur im geschlossenen Stromkreis', 'Nur bei offenem Schalter'], correct: 1,
    fb: ['Nicht immer – der Kreis muss geschlossen sein.',
         'Richtig! Strom fließt nur im vollständig geschlossenen Stromkreis.',
         'Bei offenem Schalter ist der Kreis unterbrochen – kein Strom.'] },
  { q: '2. Der Schalter ist offen. Was macht die Lampe?',
    opts: ['Sie leuchtet', 'Sie ist aus', 'Sie blinkt'], correct: 1,
    fb: ['Offener Schalter unterbricht den Kreis.',
         'Richtig! Offener Schalter → kein Strom → Lampe aus.',
         'Sie blinkt nicht – sie bleibt einfach aus.'] },
  { q: '3. Was gehört mindestens zu einem Stromkreis?',
    opts: ['Nur eine Batterie', 'Batterie, Leiter und Verbraucher (geschlossen)', 'Nur ein Kabel'], correct: 1,
    fb: ['Eine Batterie allein reicht nicht.',
         'Richtig! Energiequelle, Leiter und Verbraucher – geschlossen verbunden.',
         'Ein Kabel allein ist noch kein Stromkreis.'] }
];
function _lmpMiniHTML() {
  return _LMP_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_lmpAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="lmpFb${qi}"></div></div>`).join('');
}
function _lmpAns(qi, oi) {
  const m = _LMP_MINI[qi], el = document.getElementById('lmpFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _lmpSelf(n) {
  const out = document.getElementById('lmpSelfOut'), val = document.getElementById('lmpSelfVal');
  if (val) { val.value = String(n); _abSave('lampe'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.2.2  WELCHE STOFFE LEITEN ELEKTRISCHEN STROM?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Strom und Magnetismus"
// Handlungsorientiert: In eine Lücke des Stromkreises werden
// nacheinander Materialien eingesetzt. Leitet der Stoff, leuchtet
// die Lampe (Leiter); leitet er nicht, bleibt sie aus (Nichtleiter).
// Sortieren + Regel. Nur ungefährliche Kleinspannung.
// ═══════════════════════════════════════════════════════

const _LEI_MAT = [
  { k: 'kupfer',  name: 'Kupfer-Draht',    ic: '🧵', leit: true },
  { k: 'eisen',   name: 'Eisen-Nagel',     ic: '🔩', leit: true },
  { k: 'alu',     name: 'Alu-Löffel',      ic: '🥄', leit: true },
  { k: 'graphit', name: 'Bleistiftmine',   ic: '✏️', leit: true },
  { k: 'holz',    name: 'Holz-Stab',       ic: '🪵', leit: false },
  { k: 'plastik', name: 'Plastik-Lineal',  ic: '📏', leit: false },
  { k: 'glas',    name: 'Glas-Stab',       ic: '🔮', leit: false },
  { k: 'gummi',   name: 'Radiergummi',     ic: '🧽', leit: false }
];
let _lei = null;
function _leiInit() { _lei = { cur: 0, tested: {}, order: [], t: 0, flash: 0 }; }
function _leiOn() { const m = _LEI_MAT[_lei.cur]; return _lei.tested[m.k] !== undefined && m.leit; }

function _leiHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim lei-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🔌 Welche Stoffe leiten elektrischen Strom?</h3>
    <div class="fpm-note" style="margin-top:2px">Setze ein Material in die Lücke des Stromkreises. Leuchtet die Lampe? Dann leitet der Stoff (Leiter). Sortiere und finde die Regel. (Nur Batterie-Kleinspannung.)</div>
    <div class="fpm-grid">
      <div>
        <canvas id="leiAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="fpm-label" style="margin-top:8px">Klicke ein Material an – es wird in die Lücke gesetzt:</div>
        <div class="msf-chips" id="leiChips">${_leiChipsHTML()}</div>
        <div class="sim-btn-row" style="margin-top:6px"><button class="sim-btn" onclick="_leiReset()">🔄 Alles zurücksetzen</button></div>
      </div>
      <div>
        <div class="fpm-label">Beobachtung – deine zwei Gruppen</div>
        <div class="msf-sort">
          <div class="msf-col msf-yes"><div class="msf-col-h">💡 Lampe leuchtet – Leiter</div><div id="leiYes"></div></div>
          <div class="msf-col msf-no"><div class="msf-col-h">🚫 Lampe aus – Nichtleiter</div><div id="leiNo"></div></div>
        </div>
        <div class="fpm-tablewrap" style="margin-top:10px">
          <table class="sim-table">
            <thead><tr><th>Material</th><th>leitet Strom?</th></tr></thead>
            <tbody id="leiTbody"></tbody>
          </table>
          <div class="fpm-empty" id="leiEmpty">Noch nichts getestet.<br>Klicke oben ein Material an.</div>
        </div>
        <div class="msf-regel" id="leiRegel"></div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      <b>Metalle leiten</b> (Kupfer, Eisen, Alu) – auch <b>Graphit</b>. &nbsp;|&nbsp; Holz, Plastik, Glas, Gummi leiten nicht (Nichtleiter/Isolatoren).
    </p>
    ${_leiArbeitsblattHTML()}
  </div>`;
}
function _leiChipsHTML() {
  return _LEI_MAT.map((m, i) => {
    const t = _lei.tested[m.k];
    const cls = t === undefined ? '' : (t ? ' yes' : ' no');
    const mark = t === undefined ? '' : (t ? ' 💡' : ' ✗');
    return `<button class="msf-chip${cls}${i === _lei.cur ? ' cur' : ''}" onclick="_leiTestMat(${i})">${m.ic} ${m.name}${mark}</button>`;
  }).join('');
}

// ── Bedienung ──────────────────────────────────────────
function _leiTestMat(i) {
  _lei.cur = i; const m = _LEI_MAT[i];
  if (_lei.tested[m.k] === undefined) _lei.order.push(m.k);
  _lei.tested[m.k] = m.leit; _lei.flash = 1;
  _leiRender();
}
function _leiReset() {
  if (_lei.order.length && !confirm('Alle Testergebnisse zurücksetzen?')) return;
  _lei.tested = {}; _lei.order = []; _leiRender();
}
function _leiRender() {
  const chips = document.getElementById('leiChips'); if (chips) chips.innerHTML = _leiChipsHTML();
  const yes = document.getElementById('leiYes'), no = document.getElementById('leiNo');
  const mk = arr => arr.map(k => { const m = _LEI_MAT.find(x => x.k === k); return `<span class="msf-tag">${m.ic} ${m.name}</span>`; }).join('') || '<span class="msf-none">– noch leer –</span>';
  if (yes) yes.innerHTML = mk(_lei.order.filter(k => _lei.tested[k]));
  if (no) no.innerHTML = mk(_lei.order.filter(k => !_lei.tested[k]));
  const tb = document.getElementById('leiTbody'), empty = document.getElementById('leiEmpty');
  if (empty) empty.style.display = _lei.order.length ? 'none' : 'block';
  if (tb) tb.innerHTML = _lei.order.map(k => { const m = _LEI_MAT.find(x => x.k === k); return `<tr><td>${m.ic} ${m.name}</td><td><b class="${m.leit ? 'msf-ja' : 'msf-nein'}">${m.leit ? 'Ja' : 'Nein'}</b></td></tr>`; }).join('');
  const reg = document.getElementById('leiRegel');
  if (reg) {
    reg.style.display = 'block';
    reg.innerHTML = _lei.order.length >= _LEI_MAT.length
      ? '🎯 <b>Alle getestet!</b> Strom leiten die <b>Metalle</b> (Kupfer, Eisen, Aluminium) und <b>Graphit</b> (Bleistiftmine). Holz, Plastik, Glas und Gummi leiten <b>nicht</b> – das sind Nichtleiter (Isolatoren).'
      : 'Getestet: ' + _lei.order.length + ' von ' + _LEI_MAT.length + '. Teste alle Materialien und finde die Regel!';
  }
}

// ── Animation ──────────────────────────────────────────
function _leiUpdate(dt) { if (_lei) { _lei.t += dt; _lei.flash = Math.max(0, _lei.flash - dt * 2); } }
function _leiDraw(ctx, cv) {
  if (!_lei) return;
  const W = cv.width, H = cv.height, on = _leiOn();
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, W, H);
  const L = 60, R = W - 60, T = 45, B = H - 55;
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 4; ctx.strokeRect(L, T, R - L, B - T);
  if (on) { ctx.strokeStyle = '#22c55e'; ctx.lineWidth = 3; ctx.setLineDash([9, 9]); ctx.lineDashOffset = -(_lei.t * 70) % 18; ctx.strokeRect(L, T, R - L, B - T); ctx.setLineDash([]); ctx.lineDashOffset = 0; }
  const cx = (L + R) / 2;
  // Batterie unten
  ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(cx - 8, B - 14); ctx.lineTo(cx - 8, B + 14); ctx.stroke();
  ctx.lineWidth = 6; ctx.beginPath(); ctx.moveTo(cx + 8, B - 8); ctx.lineTo(cx + 8, B + 8); ctx.stroke();
  ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Batterie', cx, B + 26);
  // Lücke mit Klemmen (oben)
  const gx1 = cx - 44, gx2 = cx + 44;
  ctx.fillStyle = '#f8fafc'; ctx.fillRect(gx1, T - 3, gx2 - gx1, 6);
  ctx.fillStyle = '#f59e0b'; ctx.fillRect(gx1 - 6, T - 8, 8, 16); ctx.fillRect(gx2 - 2, T - 8, 8, 16);   // Klemmen
  // Material in der Lücke
  const m = _LEI_MAT[_lei.cur];
  ctx.font = '26px sans-serif'; ctx.textAlign = 'center'; ctx.fillText(m.ic, cx, T + 9);
  ctx.fillStyle = '#334155'; ctx.font = '700 12px sans-serif'; ctx.fillText(m.name, cx, T - 16);
  // Lampe (rechts)
  const ly = (T + B) / 2, lx = R, lr = 15;
  if (on) { ctx.fillStyle = 'rgba(250,204,21,0.35)'; ctx.beginPath(); ctx.arc(lx, ly, lr + 11, 0, 2 * Math.PI); ctx.fill(); }
  ctx.fillStyle = on ? '#fde047' : '#e2e8f0'; ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(lx, ly, lr, 0, 2 * Math.PI); ctx.fill(); ctx.stroke();
  ctx.strokeStyle = on ? '#b45309' : '#94a3b8'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(lx - 7, ly - 7); ctx.lineTo(lx + 7, ly + 7); ctx.moveTo(lx + 7, ly - 7); ctx.lineTo(lx - 7, ly + 7); ctx.stroke();
  ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.fillText('Lampe', lx, ly + lr + 16);
  // Ergebnis
  ctx.textAlign = 'left'; ctx.font = '700 13px sans-serif';
  if (_lei.tested[m.k] === undefined) { ctx.fillStyle = '#94a3b8'; ctx.fillText('Klicke ein Material an', L, T - 20); }
  else if (m.leit) { ctx.fillStyle = '#16a34a'; ctx.fillText('→ Lampe leuchtet: Leiter', L, T - 20); }
  else { ctx.fillStyle = '#b45309'; ctx.fillText('→ Lampe aus: Nichtleiter', L, T - 20); }
}

